/// Verifies an integer element read through a possibly-missing nested array is refused by name.
///
/// main's EIR types the inner read as a plain `int`, which cannot carry the `null` (and the
/// warning) php answers for a missing key; the audit admits such a read only when the index
/// is proven in bounds, so this shape is refused rather than answered with a wrong `0`.
/// Lowering it needs the read to keep its nullable form, which is follow-up work.
#[test]
fn test_cli_wasm_hash_container_reads_preserve_nullable_php_values() {
    let dir = make_cli_test_dir("elephc_cli_wasm_refused_hash_container_reads_preserve_");
    let refusal = wasm_audit_refusal(
        &dir,
        "main.php",
        r#"<?php
class Item {
    public function value(): int {
        return 3;
    }
}
$arrays = ["hit" => [1]];
$hashes = ["hit" => ["x" => 2]];
$objects = ["hit" => new Item()];
echo is_null($arrays["missing"]), ":", is_null($arrays["hit"]), ";";
echo is_null($hashes["missing"]), ":", is_null($hashes["hit"]), ";";
echo is_null($objects["missing"]), ":", is_null($objects["hit"]), ";";
echo $arrays["hit"][0], ":", $hashes["hit"]["x"], ";";
echo $objects["hit"]->value(), ";";
echo is_null($arrays["hit"][99]), ":", is_null($hashes["hit"]["missing"]), ";";
"#,
    );
    assert!(
        refusal.contains("element Int cannot lower into I64/Int"),
        "unexpected refusal: {refusal}"
    );
    let _ = fs::remove_dir_all(&dir);
}

