/// The static-property probe. `Child::$shared` and `Base::$shared` must both read 106 after
/// two separate increments — one through each name — which is what proves an inherited static
/// is ONE slot and not a per-class copy.
const STATIC_PROPERTY_SOURCE: &str = r##"<?php
class Base {
    public static int $shared = 100;
    public static string $tag = "base";
    public static float $ratio = 1.5;
    public static bool $on = false;
}
class Child extends Base {}
class Scoped {
    public static int $shared = 100;
    public static array $log = [];
    public static array $seeded = [3, 5];

    // `self::` is a COMPILE-TIME scope: it names the class this method is written in.
    public static function note(int $value): int {
        self::$log[] = $value;
        return count(self::$log);
    }
}
class Late extends Scoped {
    public static int $shared = 7;
    public static array $log = [];

    // `static::` is not: it names the CALLED class, so `Late::bump()` must reach Late's own
    // slots and leave Scoped's alone.
    public static function bump(): int {
        static::$shared = static::$shared + 1;
        static::$log[] = static::$shared;
        return count(static::$log);
    }
}
class Counter {
    public static int $n = 0;
    public static function tick(): int { Counter::$n = Counter::$n + 1; return Counter::$n; }
    public static function reset(): void { Counter::$n = 0; }
}
echo Base::$shared, ",", Base::$tag, ",", Base::$ratio, ",", Base::$on ? "y" : "n", ";";
Base::$shared = Base::$shared + 5;
Child::$shared = Child::$shared + 1;
echo Base::$shared, ",", Child::$shared, ";";
Base::$tag = "changed";
echo Base::$tag, ",", Child::$tag, ";";
Base::$tag = Base::$tag . "!";
echo Base::$tag, ";";
Counter::tick(); Counter::tick(); Counter::tick();
echo Counter::$n, ";";
Counter::reset();
echo Counter::$n, ";";
Base::$ratio = Base::$ratio * 2;
Base::$on = true;
echo Base::$ratio, ",", Base::$on ? "y" : "n", ";";
echo count(Scoped::$log), ",", count(Scoped::$seeded), ",", Scoped::$seeded[1], ";";
echo Scoped::note(11), ",", Scoped::note(22), ",", count(Scoped::$log), ";";
echo Late::bump(), ",", Late::bump(), ",", Late::$shared, ",", Scoped::$shared, ";";
Scoped::$seeded[1] = Scoped::$seeded[1] + 4;
echo Scoped::$seeded[1], "\n";
"##;

/// Argument unpacking, `f(...$args)`, across the element storages a spread can carry.
///
/// A spread is three conversions in a row, and each was refused on its own:
///
/// * the elements arrive as `int|null` — an element read MIGHT miss — and the callee declares
///   `int`, one word, so the pair narrows to its payload;
/// * a FLOAT element had no proven-in-bounds read at all, only the boxed one, because there is
///   no float value free to mean "missing";
/// * and the proof itself: a spread does not test `i < len` per element, it tests `len >= k`
///   once and then reads constants, which is a different shape from the loop the audit knew.
///
/// So the probe spreads an int pair, a computed array, a spread after a positional argument, a
/// float whose payload carries BITS, a string pair that has its own storage and no tag, a
/// variadic, and a static method — four call lowerings and four element storages.
