/// Verifies the pattern engine answers what php-src answers, case by case, under Node.
///
/// `preg_match` on this target is a SUBSET of PCRE compiled when the module is built, run by
/// a backtracking VM written in WAT. A subset is only honest if two things hold, and this test
/// is one of them: everything inside the subset must agree with php exactly. The other half —
/// that everything outside it is refused by NAME at compile time — is
/// `codegen_wasm::regex::tests::unimplemented_constructs_are_refused_by_name`.
///
/// Every expectation below was MEASURED against php-src 8.5.10 rather than reasoned about,
/// and the table covers each rule the engine had to get right: `$` before a trailing newline
/// but not before an inner one, `\z` refusing even the trailing one, `.` stopping at a newline
/// until `s`, `^` per-line only under `m`, `\b` at both ends of the subject, a lazy quantifier
/// preferring the shortest match, `{n,}` requiring n and not n+1, a `]` first in a class being
/// a literal, and case folding reaching both literals and ranges.
///
/// The last block is the one a fuzz found. A loop whose body can match NOTHING — `(?:a?)*` —
/// returns to its own head at the same offset, and without a progress check the VM does that
/// until its step budget runs out and then answers 0, taking the alternatives that would have
/// matched with it. Fifteen of four hundred random patterns hit it; the differential now runs
/// clean at fifteen hundred.
#[test]
fn test_cli_wasm_preg_match_matches_php() {
    let dir = make_cli_test_dir("elephc_cli_wasm_preg");
    let php_path = dir.join("main.php");
    fs::write(&php_path, PREG_PROBE).unwrap();

    let output = elephc_cli_command(&dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(&php_path)
        .output()
        .expect("failed to compile the preg probe");
    assert!(
        output.status.success(),
        "preg probe failed to compile: {}",
        String::from_utf8_lossy(&output.stderr)
    );

    if node_missing_skips_test() {
        let _ = fs::remove_dir_all(&dir);
        return;
    }
    let runner = dir.join("run.mjs");
    fs::write(
        &runner,
        r#"import { readFileSync } from "node:fs";
import { WASI } from "node:wasi";
const wasi = new WASI({ version: "preview1", args: ["m"], env: {}, returnOnExit: true });
const bytes = readFileSync(process.argv[2]);
const instance = await WebAssembly.instantiate(
  await WebAssembly.compile(bytes),
  wasi.getImportObject(),
);
process.exitCode = wasi.start(instance);
"#,
    )
    .unwrap();
    let run = node_command()
        .arg("--no-warnings")
        .arg(&runner)
        .arg(dir.join("main.wasm"))
        .current_dir(&dir)
        .output()
        .expect("failed to run the preg probe under Node");
    let expected = concat!(
            "0=1\n",
            "1=0\n",
            "2=0\n",
            "3=1\n",
            "4=1\n",
            "5=0\n",
            "6=1\n",
            "7=0\n",
            "8=1\n",
            "9=0\n",
            "10=1\n",
            "11=1\n",
            "12=0\n",
            "13=1\n",
            "14=1\n",
            "15=0\n",
            "16=1\n",
            "17=0\n",
            "18=1\n",
            "19=0\n",
            "20=1\n",
            "21=1\n",
            "22=1\n",
            "23=0\n",
            "24=1\n",
            "25=1\n",
            "26=0\n",
            "27=1\n",
            "28=1\n",
            "29=0\n",
            "30=1\n",
            "31=1\n",
            "32=1\n",
            "33=1\n",
            "34=1\n",
            "35=0\n",
            "36=1\n",
            "37=1\n",
            "38=1\n",
            "39=0\n",
            "40=1\n",
            "41=0\n",
            "42=1\n",
            "43=0\n",
            "44=1\n",
            "45=1\n",
            "46=1\n",
            "47=1\n",
            "48=1\n",
            "49=1\n",
            "50=1\n",
            "51=0\n",
            "52=1\n",
            "53=0\n",
            "54=1\n",
            "55=1\n",
            "56=1\n",
            "57=0\n",
            "58=1\n",
            "59=1\n",
            "60=1\n",
            "61=1\n",
            "62=1\n",
            "63=1\n",
            "64=1\n",
            "65=1\n",
            "66=1\n",
            "67=1\n",
            "68=1\n",
            "69=0\n",
            "70=1\n",
    );
    assert_eq!(String::from_utf8_lossy(&run.stdout), expected);

    // php-src is the reference, not this test's own expectation.
    let php = Command::new("php")
        .arg("-n")
        .arg(&php_path)
        .current_dir(&dir)
        .output();
    // The pinned text above is the assertion; php-src confirms it where a host has php. CI's
    // Linux containers do not, and a missing php is not a failure of this target.
    if let Some(php) = php.ok().filter(|php| php.status.success()) {
        assert_eq!(
            String::from_utf8_lossy(&php.stdout),
            expected,
            "php-src and the pattern VM disagree"
        );
    }

    // A pattern the engine does not implement is a COMPILE error naming the construct, which
    // is the whole basis on which a partial engine is safe to ship.
    for (pattern, named) in [
        (r"/(a)\1/", "backreference"),
        (r"/(?=a)/", "lookahead"),
        (r"/\p{L}/", "unicode property"),
        (r"/a*+/", "possessive"),
        (r"/abc/u", "UTF-8"),
    ] {
        fs::write(
            &php_path,
            format!("<?php\necho preg_match('{pattern}', \"x\");\n"),
        )
        .unwrap();
        let output = elephc_cli_command(&dir)
            .arg("--target")
            .arg("wasm32-wasi")
            .arg(&php_path)
            .output()
            .expect("failed to run the refusal probe");
        assert!(!output.status.success(), "{pattern} must be refused");
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            stderr.contains(named),
            "{pattern} was refused without naming {named:?}: {stderr}"
        );
    }

    // And `$matches`, whose absence a program could not otherwise detect.
    fs::write(
        &php_path,
        "<?php\n$m = [];\necho preg_match('/a/', \"a\", $m);\n",
    )
    .unwrap();
    let output = elephc_cli_command(&dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(&php_path)
        .output()
        .expect("failed to run the $matches probe");
    assert!(!output.status.success(), "$matches must be refused");
    assert!(String::from_utf8_lossy(&output.stderr).contains("$matches"));

    let _ = fs::remove_dir_all(&dir);
}

