/// Verifies `abs(int)` answers php's `int|float` on wasm32-wasi.
///
/// `abs` is the one direct builtin whose result type is not decided by its argument type
/// alone: PHP_INT_MIN has no positive counterpart, so php answers the FLOAT
/// 9.2233720368548E+18 for that single argument and an int for every other — measured on
/// php-src 8.5.6. The EIR says so with a boxed result, and the wasm lowering used to refuse
/// it outright because its table expected a raw `I64`. The arguments come out of an array so
/// none of them folds at compile time.
#[test]
fn test_cli_wasm_int_abs_overflows_to_float_like_php() {
    if node_missing_skips_test() {
        return;
    }

    let dir = make_cli_test_dir("elephc_cli_wasm_int_abs");
    let php_path = dir.join("main.php");
    fs::write(
        &php_path,
        r#"<?php
function ints(int $n): void { $a = abs($n); echo gettype($a), "(", $a, ")\n"; }
foreach ([-3, 3, 0, PHP_INT_MAX, PHP_INT_MIN, PHP_INT_MIN + 1] as $v) { ints($v); }
function floats(float $x): void { $a = abs($x); echo gettype($a), "(", $a, ")\n"; }
foreach ([-2.5, 0.0, -0.0] as $v) { floats($v); }
"#,
    )
    .unwrap();

    let output = elephc_cli_command(&dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(&php_path)
        .output()
        .expect("failed to compile the abs probe to WASM");
    assert!(
        output.status.success(),
        "abs failed to compile: {}",
        String::from_utf8_lossy(&output.stderr)
    );

    let runner = dir.join("run.mjs");
    fs::write(
        &runner,
        r#"import { readFileSync } from "node:fs";
import { WASI } from "node:wasi";
const wasi = new WASI({ version: "preview1", args: ["m"], env: {}, returnOnExit: true });
const bytes = readFileSync(process.argv[2]);
const instance = await WebAssembly.instantiate(
  await WebAssembly.compile(bytes),
  wasi.getImportObject(),
);
process.exitCode = wasi.start(instance);
"#,
    )
    .unwrap();

    let run = node_command()
        .arg("--no-warnings")
        .arg(&runner)
        .arg(dir.join("main.wasm"))
        .current_dir(&dir)
        .output()
        .expect("failed to run the abs probe under Node");
    assert_eq!(
        String::from_utf8_lossy(&run.stdout),
        concat!(
            "integer(3)\n",
            "integer(3)\n",
            "integer(0)\n",
            "integer(9223372036854775807)\n",
            "double(9.2233720368548E+18)\n",
            "integer(9223372036854775807)\n",
            "double(2.5)\n",
            "double(0)\n",
            "double(0)\n",
        ),
        "php -n's own answers ({})",
        String::from_utf8_lossy(&run.stderr)
    );

    let _ = fs::remove_dir_all(&dir);
}

/// Verifies RFC 2397 `data:` URIs decode into ordinary readable streams on wasm32-wasi.
///
/// Every line is `php -n`'s own answer, measured on php-src 8.5.6 — including the four that
/// FAIL, which is where the rules actually live: `;BASE64` is not a base64 marker (php compares
/// that literal case-sensitively) AND not a valid parameter, because every `;` parameter must
/// carry an `=` — `;charset=utf-8` opens, `;foo` does not. Base64 here is STRICT, unlike the
/// `base64_decode` builtin: whitespace and padding are skipped but a stray byte fails the open.
/// A plain payload is `urldecode`, so `+` is a space and a `%` without two hex digits is literal.
#[test]
fn test_cli_wasm_data_uris_decode_like_php() {
    if node_missing_skips_test() {
        return;
    }

    let dir = make_cli_test_dir("elephc_cli_wasm_data_uri");
    let php_path = dir.join("main.php");
    fs::write(
        &php_path,
        r#"<?php
function show(string $uri): void {
    $h = @fopen($uri, "r");
    if ($h === false) { echo "FALSE\n"; return; }
    $body = stream_get_contents($h);
    echo strlen($body), ":", $body, "\n";
    fclose($h);
}
show("data://text/plain;base64,SGVsbG8sIHdvcmxkIQ==");
show("data://text/plain,inline%20text%2C+decoded");
show("data:,bare-no-slashes");
show("data://text/plain,100%");
show("data://text/plain;base64,SGVs bG8");
show("data://text/plain;charset=utf-8,hi");
show("data://text/plain;base64,####");
show("data://text/plain;BASE64,SGVsbG8=");
show("data://text/plain;foo,hi");
show("data://text/plain");
"#,
    )
    .unwrap();

    let output = elephc_cli_command(&dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(&php_path)
        .output()
        .expect("failed to compile the data: URI probe to WASM");
    assert!(
        output.status.success(),
        "data: URIs failed to compile: {}",
        String::from_utf8_lossy(&output.stderr)
    );

    let runner = dir.join("run.mjs");
    fs::write(
        &runner,
        r#"import { readFileSync } from "node:fs";
import { WASI } from "node:wasi";
const wasi = new WASI({ version: "preview1", args: ["m"], env: {}, returnOnExit: true });
const bytes = readFileSync(process.argv[2]);
const instance = await WebAssembly.instantiate(
  await WebAssembly.compile(bytes),
  wasi.getImportObject(),
);
process.exitCode = wasi.start(instance);
"#,
    )
    .unwrap();

    let run = node_command()
        .arg("--no-warnings")
        .arg(&runner)
        .arg(dir.join("main.wasm"))
        .current_dir(&dir)
        .output()
        .expect("failed to run the data: URI probe under Node");
    assert_eq!(
        String::from_utf8_lossy(&run.stdout),
        concat!(
            "13:Hello, world!\n",
            "20:inline text, decoded\n",
            "15:bare-no-slashes\n",
            "4:100%\n",
            "5:Hello\n",
            "2:hi\n",
            "FALSE\n",
            "FALSE\n",
            "FALSE\n",
            "FALSE\n",
        ),
        "php -n's own answers ({})",
        String::from_utf8_lossy(&run.stderr)
    );

    let _ = fs::remove_dir_all(&dir);
}

