/// One call of each, over hashes, on the values where php's answer is the surprising one.
const ARRAY_PARITY_PHP: &str = r##"<?php
function yes_no(bool $flag): string
{
    return $flag ? "yes" : "no";
}

function render(array $rows): string
{
    $parts = [];
    foreach ($rows as $key => $value) {
        $parts[] = $key . "=" . $value;
    }
    return implode(",", $parts);
}

// `array_is_list` reads the insertion ORDER, not the key set: the second array holds the keys
// 0 and 1 of a two-element list and is still not one.
$named = ["first" => 1, "second" => 2];
$reordered = [1 => "b", 0 => "a"];
echo "is_list named: ", yes_no(array_is_list($named)), "\n";
echo "is_list reordered: ", yes_no(array_is_list($reordered)), "\n";

// The two edges come back in the key's own kind, and `null` — not `false` — for an empty array.
$ages = ["ada" => 36, "linus" => 54, "grace" => 45];
echo "first: ", array_key_first($ages), "\n";
echo "last: ", array_key_last($ages), "\n";

// `array_replace` keeps the LEFT key order and appends only genuinely new keys.
$base = ["host" => "localhost", "port" => 80, "tls" => 0];
$override = ["port" => 443, "tls" => 1, "sni" => "example.test"];
echo "replace: ", render(array_replace($base, $override)), "\n";

// The `_assoc` set operations compare the KEY and the VALUE, and php renders the values as
// strings before comparing: 1 and "1" are equal, while 0 and "0.0" are not.
$left = ["a" => 1, "b" => 2, "c" => 0];
$right = ["a" => "1", "b" => 9, "c" => "0.0"];
echo "diff_assoc: ", render(array_diff_assoc($left, $right)), "\n";
echo "intersect_assoc: ", render(array_intersect_assoc($left, $right)), "\n";
"##;

/// A local rebound to another type clears its old slot instead of leaving a live pointer in it.
///
/// `$q = "a" . $n; $r = $q; $q = 1;` is the shape: `$q`'s slot keeps the STRING storage the
/// frame epilogue walks, and the pointer sitting there is the one `$r` now owns. Leaving it
/// would free a live buffer at the epilogue — measured as four NUL bytes on the native backend
/// before `Op::ZeroLocalSlot` existed, with allocations and frees still balanced because the
/// block freed was a genuinely live one. The loop form repeats it once per iteration.
#[test]
fn test_cli_wasm_abandoned_binding_clears_its_slot() {
    if node_missing_skips_test() {
        return;
    }

    let dir = make_cli_test_dir("elephc_cli_wasm_abandoned_binding");
    let php_path = dir.join("main.php");
    fs::write(&php_path, ABANDONED_BINDING_PHP).unwrap();

    let output = elephc_cli_command(&dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(&php_path)
        .output()
        .expect("failed to compile the abandoned-binding probe to WASM");
    assert!(
        output.status.success(),
        "abandoned-binding compilation failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );

    let runner = dir.join("run.mjs");
    fs::write(
        &runner,
        r#"import { readFileSync } from "node:fs";
import { WASI } from "node:wasi";
const wasi = new WASI({ version: "preview1", args: ["m"], env: {}, returnOnExit: true, preopens: { ".": "." } });
const bytes = readFileSync(process.argv[2]);
const instance = await WebAssembly.instantiate(
  await WebAssembly.compile(bytes),
  wasi.getImportObject(),
);
process.exitCode = wasi.start(instance);
"#,
    )
    .unwrap();

    let run = node_command()
        .arg("--no-warnings")
        .arg(&runner)
        .arg(dir.join("main.wasm"))
        .current_dir(&dir)
        .output()
        .expect("failed to run the abandoned-binding probe under Node");
    assert!(
        run.status.success(),
        "the abandoned-binding probe trapped: {}",
        String::from_utf8_lossy(&run.stderr)
    );

    // php 8.5.10's own output for the same file.
    assert_eq!(
        String::from_utf8_lossy(&run.stdout),
        "a7|1\na8|1\nv0:0 v1:1 v2:2 \n",
    );

    let _ = fs::remove_dir_all(&dir);
}

/// A rebinding that abandons heap storage, once straight-line and once per loop iteration.
const ABANDONED_BINDING_PHP: &str = r##"<?php
// `$q` holds a heap string, then is rebound to an int. Its slot keeps the string's storage
// type, so the frame epilogue still walks it — and the pointer left there belongs to `$r`.
function probe(int $n): string
{
    $q = "a" . $n;
    $r = $q;
    $q = 1;
    return $r . "|" . $q;
}

echo probe(7), "\n";
echo probe(8), "\n";

// The same shape through a loop, where the slot is written on every iteration.
function repeated(int $rounds): string
{
    $out = "";
    for ($i = 0; $i < $rounds; $i++) {
        $held = "v" . $i;
        $kept = $held;
        // `(int)`: `$i++` types the counter `int|float`, which the checker will not rebind a
        // string slot to; the rebinding to an int is what this probe is about.
        $held = (int) $i;
        $out = $out . $kept . ":" . $held . " ";
    }
    return $out;
}

echo repeated(3), "\n";
"##;

/// A copy of a boxed value is a cell of its own: rebinding the copy leaves the source alone.
///
/// A `mixed` parameter is shadowed by a private copy before the body can rebind it, and a
/// by-value assignment of a boxed value copies its cell — both `mixed_clone`. Sharing the cell
/// would make `relabel($o)` rewrite the caller's `$o`.
#[test]
fn test_cli_wasm_mixed_copies_do_not_share_their_cell() {
    if node_missing_skips_test() {
        return;
    }

    let dir = make_cli_test_dir("elephc_cli_wasm_mixed_clone");
    let php_path = dir.join("main.php");
    fs::write(&php_path, MIXED_CLONE_PHP).unwrap();

    let output = elephc_cli_command(&dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(&php_path)
        .output()
        .expect("failed to compile the probe to WASM");
    assert!(
        output.status.success(),
        "compilation failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );

    let runner = dir.join("run.mjs");
    fs::write(
        &runner,
        r#"import { readFileSync } from "node:fs";
import { WASI } from "node:wasi";
const wasi = new WASI({ version: "preview1", args: ["m"], env: {}, returnOnExit: true, preopens: { ".": "." } });
const bytes = readFileSync(process.argv[2]);
const instance = await WebAssembly.instantiate(
  await WebAssembly.compile(bytes),
  wasi.getImportObject(),
);
process.exitCode = wasi.start(instance);
"#,
    )
    .unwrap();

    let run = node_command()
        .arg("--no-warnings")
        .arg(&runner)
        .arg(dir.join("main.wasm"))
        .current_dir(&dir)
        .output()
        .expect("failed to run the probe under Node");
    assert!(
        run.status.success(),
        "the probe trapped: {}",
        String::from_utf8_lossy(&run.stderr)
    );

    // php 8.5's own output for the same file.
    assert_eq!(String::from_utf8_lossy(&run.stdout), "changed orig\narray:3 array:3\nstr str!\n350\n");

    let _ = fs::remove_dir_all(&dir);
}

/// Whether a by-value capture owns its slot is a RUNTIME fact, so it is tracked at run time.
///
/// The slot borrows the descriptor's value until the body stores into it. The return epilogue
/// released every capture the body could reassign, so a call that took the other branch freed the
/// descriptor's string — the next call printed `@` where php prints `x` — and an object capture
/// died with `Invalid callable dispatch`. A second reassignment, for its part, skipped the release
/// of the first one's value and grew memory without bound (312 pages over 20000 calls). One flag
/// per reassigned capture, set by a store, now decides both releases.
#[test]
fn test_cli_wasm_capture_released_only_after_a_store() {
    if node_missing_skips_test() {
        return;
    }

    let dir = make_cli_test_dir("elephc_cli_wasm_capture_owned_flag");
    let runner = dir.join("run.mjs");
    fs::write(
        &runner,
        r#"import { readFileSync } from "node:fs";
import { WASI } from "node:wasi";
const wasi = new WASI({ version: "preview1", args: ["m"], env: {}, returnOnExit: true });
const instance = await WebAssembly.instantiate(
  await WebAssembly.compile(readFileSync(process.argv[2])),
  wasi.getImportObject(),
);
const code = wasi.start(instance);
console.error(`pages=${instance.exports.memory.buffer.byteLength / 65536}`);
process.exitCode = code;
"#,
    )
    .unwrap();

    // php-src 8.5.6's own answers.
    for (name, source, expected, max_growth) in [
        (
            "branches.php",
            r#"<?php
$s = "x" . count([1]);
$f = function (bool $c) use ($s) { if ($c) { $s = str_repeat("a", 10); } return strlen($s) . $s[0]; };
echo $f(false), " ", $f(false), " ", $f(true), " ", $f(false), " ", $s, "\n";
$o = new ArrayObject([1, 2]);
$g = function (bool $c) use ($o) { if ($c) { $o = new ArrayObject([9]); } return count($o); };
echo $g(false), " ", $g(false), " ", $g(true), " ", $g(false), " ", count($o), "\n";
"#,
            "2x 2x 10a 2x x1\n2 2 1 2 2\n",
            None,
        ),
        (
            "balance.php",
            r#"<?php
$s = "x" . count([1]);
$t = "y" . count([1]);
$n = 0;
for ($i = 0; $i < 20000; $i++) {
    $c = $i % 2;
    $f = function () use ($s, $c) { if ($c > 0) { $s = str_repeat("a", 1000); } return strlen($s); };
    $n += $f();
    $n += $f();
    $g = function () use ($t) { $t = str_repeat("a", 1000); $t = str_repeat("b", 1000); return strlen($t); };
    $n += $g();
}
echo $n, " ", $s, $t, "\n";
"#,
            "40040000 x1y1\n",
            Some(2usize),
        ),
    ] {
        let path = dir.join(name);
        fs::write(&path, source).unwrap();
        for extra in [vec!["--emit-asm"], vec![]] {
            let mut command = elephc_cli_command(&dir);
            command.arg("--target").arg("wasm32-wasi");
            for flag in extra {
                command.arg(flag);
            }
            let built = command.arg(&path).output().expect("failed to invoke elephc");
            assert!(
                built.status.success(),
                "{name} failed to compile: {}",
                String::from_utf8_lossy(&built.stderr)
            );
        }
        let stem = name.trim_end_matches(".php");
        let run = node_command()
            .arg("--no-warnings")
            .arg(&runner)
            .arg(dir.join(format!("{stem}.wasm")))
            .current_dir(&dir)
            .output()
            .expect("failed to run under Node");
        let stderr = String::from_utf8_lossy(&run.stderr);
        assert!(run.status.success(), "{name} trapped: {stderr}");
        assert_eq!(String::from_utf8_lossy(&run.stdout), expected, "{name}");
        if let Some(max_growth) = max_growth {
            let final_pages: usize = stderr
                .split("pages=")
                .nth(1)
                .and_then(|rest| rest.trim().parse().ok())
                .unwrap_or_else(|| panic!("{name}: the runner reported no page count"));
            let wat = fs::read_to_string(dir.join(format!("{stem}.wat"))).expect("WAT written");
            let initial_pages: usize = wat
                .split("(memory (export \"memory\") ")
                .nth(1)
                .and_then(|rest| rest.split(')').next())
                .and_then(|n| n.trim().parse().ok())
                .unwrap_or_else(|| panic!("{name}: the module declares no initial memory"));
            let grew = final_pages - initial_pages;
            assert!(
                grew <= max_growth,
                "{name}: 20000 calls grew {grew} pages: a stored capture is not released once"
            );
        }
    }

    let _ = fs::remove_dir_all(&dir);
}

/// Verifies on WASM that a closure reassigning a by-value capture leaves the captured value alive.
