/// `throw()` into an outer generator that is inside `yield from` raises in the INNER generator,
/// where it is waiting, so the inner's own `try` sees it first. When the inner does not catch,
/// the exception leaves it and propagates out of the outer, whose own `try` (or the caller)
/// handles it, exactly as php does.
#[test]
fn test_cli_wasm_yield_from_forwards_throw_to_the_inner_generator() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_yield_from_throw");
    let (stdout, _) = wasm_audit_run(
        &dir,
        "deleg_throw.php",
        r#"<?php
function inner() {
    try { yield 1; } catch (Exception $e) { echo "inner caught ", $e->getMessage(), "\n"; yield 2; }
}
function outer() { yield from inner(); yield 3; }
$g = outer();
echo $g->current(), "\n";
echo $g->throw(new Exception("boom")), "\n";
$g->next();
echo $g->current(), "\n";

function inner2() { yield 1; yield 2; }
function outer2() {
    try { yield from inner2(); } catch (Exception $e) { echo "outer caught ", $e->getMessage(), "\n"; yield 9; }
    yield 3;
}
$g = outer2();
echo $g->current(), "\n";
echo $g->throw(new Exception("boom")), "\n";
$g->next();
echo $g->current(), "\n";

function outer3() { yield from inner2(); }
$h = outer3();
echo $h->current(), "\n";
try { $h->throw(new Exception("bye")); } catch (Exception $e) { echo "main caught ", $e->getMessage(), "\n"; }
var_dump($h->valid());
"#,
    );
    assert_eq!(
        stdout,
        "1\ninner caught boom\n2\n3\n1\nouter caught boom\n9\n3\n1\nmain caught bye\nbool(false)\n"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// `ob_end_clean()` and `ob_get_clean()` still CALL the output handler, with `CLEAN|FINAL` (plus
/// `START` on its first call) and discard what it answers; `ob_get_clean()` returns the raw
/// capture. `ob_get_status()` reports the top record's own level, chunk size and buffer size
/// (the chunk size rounded up to 4096, 16384 with none), and an empty array with no buffer.
/// The handler's result must be released: the loop is measured against a handler-less control.
#[test]
fn test_cli_wasm_ob_clean_runs_the_handler_and_status_is_real() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_ob_clean_status");
    let (stdout, _) = wasm_audit_run(&dir, "obclean.php", r#"<?php
class S { public $phases = ""; }
$s = new S();
ob_start(function ($buf, $phase) use ($s) { $s->phases .= $phase . ","; return strtoupper($buf); });
echo "x";
ob_end_clean();
echo "[", $s->phases, "]\n";
ob_start(function ($buf, $phase) use ($s) { $s->phases .= $phase . ","; return strtoupper($buf); });
echo "y";
$r = ob_get_clean();
echo $r, " [", $s->phases, "]\n";
ob_start(function ($b) { return $b; }, 8);
$a = ob_get_status();
ob_start(function ($b) { return $b; }, 5000);
$b = ob_get_status();
ob_start();
$c = ob_get_status();
ob_end_clean();
ob_end_clean();
ob_end_clean();
foreach ([$a, $b, $c] as $st) {
    echo $st['level'], " ", $st['chunk_size'], " ", $st['buffer_size'], " ", $st['type'], " ", $st['flags'], "\n";
}
echo count(ob_get_status()), "\n";
"#);
    assert_eq!(
        stdout,
        "[11,]\ny [11,11,]\n0 8 4096 1 113\n1 5000 8192 1 113\n2 0 16384 0 112\n0\n"
    );

    let body = |start: &str| format!(
        "<?php\n$n = 0;\nfor ($i = 0; $i < 20000; $i++) {{\n    {start}\n    echo \"xyz\";\n    ob_end_clean();\n    $n++;\n}}\necho $n, \"\\n\";\n"
    );
    let (out, grew_handler) = wasm_audit_run(
        &dir,
        "obleak.php",
        &body("ob_start(function ($b) { return $b; });"),
    );
    assert_eq!(out, "20000\n");
    let (_, grew_control) = wasm_audit_run(&dir, "obctl.php", &body("ob_start();"));
    assert!(
        grew_handler <= grew_control + 1,
        "the discarded handler result leaked: {grew_handler} pages against the control's {grew_control}"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// A generator parameter the body reassigns to another type has a slot wider than the argument
/// that arrives. The wrapper used to store the argument at its declared width into a frame word
/// laid out for the widened Mixed slot, so `function h(string $s, int $k) { echo $s; $s = 5 + $k;
/// ... }` printed an empty string, and every parameter after a widened one was shifted. Each kind
/// the wrapper boxes (int, string, float, bool, array, object) is covered, with a trailing
/// parameter proving nothing moved; the loop proves the boxed cells are released.
#[test]
fn test_cli_wasm_generator_widened_parameters_are_boxed_by_the_wrapper() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_generator_widened_params");
    let (stdout, _) = wasm_audit_run(
        &dir,
        "widen.php",
        r#"<?php
class P { public $v = 7; }
function w(int $i, string $s, float $f, bool $b, array $a, P $o, string $tail) {
    echo $i, "|", $s, "|", $f, "|", ($b ? "true" : "false"), "|", count($a), "|", $o->v, "|", $tail, "\n";
    $i = "i$i";
    $s = 5;
    $f = "f$f";
    $b = "b";
    $a = "a";
    $o = "o";
    yield $i;
    yield $s;
    yield $f;
    yield $b;
    yield $a;
    yield $o;
    yield $tail;
}
foreach (w(4, "str", 1.5, true, [1, 2, 3], new P(), "end") as $v) { echo $v, "\n"; }
function h(string $s, int $k) { echo $s, "\n"; $s = 5 + $k; yield $s; yield $k; }
foreach (h("abc", 3) as $v) { echo $v, "\n"; }
"#,
    );
    assert_eq!(
        stdout,
        "4|str|1.5|true|3|7|end\ni4\n5\nf1.5\nb\na\no\nend\nabc\n8\n3\n"
    );

    let body = |reassign: &str| {
        format!(
            "<?php\nfunction h(string $s, array $a, int $k) {{ {reassign} yield 1; yield $k; }}\n$n = 0;\nfor ($i = 0; $i < 20000; $i++) {{\n    foreach (h(\"abc\" . $i, [1, 2, 3], 3) as $v) {{ $n += $v; }}\n}}\necho $n, \"\\n\";\n"
        )
    };
    let (out, grew) = wasm_audit_run(&dir, "widenleak.php", &body("$s = 5 + $k; $a = \"x\";"));
    assert_eq!(out, "80000\n");
    let (_, control) = wasm_audit_run(&dir, "widenctl.php", &body("$t = 5 + $k; $b = \"x\";"));
    assert!(
        grew <= control + 1,
        "widened generator parameters leaked: {grew} pages against the control's {control}"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// A generator closure that reassigns a by-value capture used to leak the wrapper's reference
/// on every call. The wrapper gives the frame a reference of its own to each argument (a private
/// copy of a string), so the capture slot OWNS its value from the start, but the release before
/// the first reassignment was skipped as though the slot still borrowed from the callable
/// descriptor. 20000 calls grew memory by 67 pages; the control, which reassigns nothing, by none.
#[test]
fn test_cli_wasm_generator_closure_releases_a_reassigned_capture() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_generator_capture_leak");
    let body = |reassign: &str| {
        format!(
            "<?php\n$o = new stdClass();\n$o->n = 1;\n$total = 0;\nfor ($i = 0; $i < 20000; $i++) {{\n    $s = str_repeat(\"a\", 200) . $i;\n    $f = function () use ($s, $o) {{ if ($s !== \"\") {{ {reassign} }} yield $s; $s = $s . \"!\"; yield $s; yield $o->n; }};\n    foreach ($f() as $v) {{ $total++; }}\n}}\necho $total, \"\\n\";\n"
        )
    };
    let (out, grew) = wasm_audit_run(&dir, "capleak.php", &body("$s = \"b\";"));
    assert_eq!(out, "60000\n");
    let (out, control) = wasm_audit_run(&dir, "capctl.php", &body("$t = \"b\";"));
    assert_eq!(out, "60000\n");
    assert!(
        grew <= control + 1,
        "a reassigned generator capture leaked: {grew} pages against the control's {control}"
    );

    let (out, _) = wasm_audit_run(
        &dir,
        "capvalues.php",
        r#"<?php
$s = "cap" . strlen("xyz");
$f = function () use ($s) {
    yield $s;
    if ($s === "none") { $s = "never"; }
    $s = $s . "1";
    yield $s;
    $s = $s . "2";
    yield $s;
};
foreach ($f() as $v) { echo $v, "\n"; }
echo $s, "\n";
"#,
    );
    assert_eq!(out, "cap3\ncap31\ncap312\ncap3\n");
    let _ = fs::remove_dir_all(&dir);
}

/// A generator that an exception LEAVES used to keep its locals forever: the landing pad marked
/// the frame terminated, and the frame's release skips the spilled locals of a terminated frame
/// (they may be stale), so nothing gave them back. 20000 such generators grew memory by 241
/// pages; the control, which ends normally, by none. The destructor order is php's: the locals
/// die when the exception leaves the body, before the catch runs, and exactly once.
#[test]
fn test_cli_wasm_generator_ended_by_an_exception_releases_its_locals() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_generator_exception_locals");
    let body = |fail: &str| {
        format!(
            "<?php\nfunction gen($i) {{ $s = str_repeat(\"x\", 300) . $i; yield 1; if ($s !== \"\") {{ {fail} }} yield 2; }}\nfor ($i = 0; $i < 20000; $i++) {{\n    $g = gen($i);\n    try {{ $g->current(); $g->next(); }} catch (Exception $e) {{}}\n    unset($g);\n}}\necho \"done\\n\";\n"
        )
    };
    let (out, grew) = wasm_audit_run(&dir, "genexc.php", &body("throw new Exception(\"e\");"));
    assert_eq!(out, "done\n");
    let (out, control) = wasm_audit_run(&dir, "genexcctl.php", &body("$s = \"\";"));
    assert_eq!(out, "done\n");
    assert!(
        grew <= control + 1,
        "a generator ended by an exception leaked its locals: {grew} pages against the control's {control}"
    );

    let (out, _) = wasm_audit_run(
        &dir,
        "gendtor.php",
        r#"<?php
class D { public $n; function __construct($n) { $this->n = $n; } function __destruct() { echo "~", $this->n, "\n"; } }
function gen($tag) {
    $a = new D("a$tag");
    $s = "str" . $tag;
    $arr = [1, 2, $tag];
    yield 1;
    $b = new D("b$tag");
    unset($b);
    echo "before throw\n";
    throw new Exception("boom$tag");
}
$g = gen(1);
$g->current();
try { $g->next(); } catch (Exception $e) { echo $e->getMessage(), "\n"; }
echo ($g->valid() ? "true" : "false"), "\n";
unset($g);
echo "after\n";
function gen2() {
    $o = new D("t");
    try { yield 1; } catch (Exception $e) { echo "caught\n"; }
    yield 2;
    $x = new D("x");
    throw new Exception("late");
}
$h = gen2();
$h->current();
$h->throw(new Exception("in"));
try { $h->next(); } catch (Exception $e) { echo $e->getMessage(), "\n"; }
unset($h);
echo "end\n";
"#,
    );
    assert_eq!(
        out,
        "~b1\nbefore throw\n~a1\nboom1\nfalse\nafter\ncaught\n~t\n~x\nlate\nend\n"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// A generator whose body threw inside a `foreach` is finished: `valid()` is false, `current()`
/// is null and the body is not resumed. `foreach` advanced the generator with a bare resume and
/// never marked it started, so the first `valid()` after the loop "primed" it and re-entered the
/// body at its stale resume point, printing "before throw" a second time.
#[test]
fn test_cli_wasm_generator_that_threw_in_foreach_stays_finished() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_generator_foreach_threw");
    let (out, _) = wasm_audit_run(
        &dir,
        "foreachthrew.php",
        r#"<?php
function gen() {
    yield 1;
    echo "before throw\n";
    throw new Exception("boom");
}
$g = gen();
try { foreach ($g as $v) { echo $v, "\n"; } } catch (Exception $e) { echo $e->getMessage(), "\n"; }
echo ($g->valid() ? "true" : "false"), "\n";
echo ($g->current() === null ? "NULL" : "value"), "\n";
function fin() { yield 1; yield 2; }
$h = fin();
foreach ($h as $v) { echo $v; }
echo ($h->valid() ? "true" : "false"), "\n";
echo "after\n";
"#,
    );
    assert_eq!(out, "1\nbefore throw\nboom\nfalse\nNULL\n12false\nafter\n");
    let _ = fs::remove_dir_all(&dir);
}

/// Calling a generator closure a SECOND time goes through the dynamic callable path, whose
/// wrapper forwarded the generator's frame pointer as though it were a boxed Mixed cell. The
/// second `foreach` then warned "argument must be of type array|object" and yielded nothing.
/// The wrapper now boxes the frame as an object, and the dynamic `foreach` walks a boxed
/// generator. The second call starts from the descriptor's captured value, not the first
/// frame's reassigned one, and nothing leaks over 20000 calls.
#[test]
fn test_cli_wasm_generator_closure_can_be_called_twice() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_generator_closure_twice");
    let (out, _) = wasm_audit_run(
        &dir,
        "twice.php",
        r#"<?php
$s = "cap" . strlen("xyz");
$f = function () use ($s) {
    yield $s;
    $s = $s . "1";
    yield $s;
};
foreach ($f() as $v) { echo $v, "\n"; }
foreach ($f() as $k => $v) { echo $k, "=", $v, "\n"; }
$g = function () { yield 1; yield 2; };
$a = $g();
$b = $g();
foreach ($a as $v) { echo $v; }
foreach ($b as $v) { echo $v; }
echo "\n";
"#,
    );
    assert_eq!(out, "cap3\ncap31\n0=cap3\n1=cap31\n1212\n");

    let (out, grew) = wasm_audit_run(
        &dir,
        "twiceleak.php",
        r#"<?php
$o = 7;
$f = function () use ($o) { yield $o; yield 2; };
$n = 0;
foreach ($f() as $v) { $n += $v; }
for ($i = 0; $i < 20000; $i++) {
    foreach ($f() as $v) { $n += $v; }
}
echo $n, "\n";
"#,
    );
    assert_eq!(out, "180009\n");
    assert!(grew <= 2, "calling a generator closure repeatedly leaked: {grew} pages");
    let _ = fs::remove_dir_all(&dir);
}

/// Returning a freshly built string used to leak the block it was built in. On this target
/// `.` and `str_repeat()` allocate an OWNED heap block, while the EIR treats their result as a
/// view and persists a copy for the return without ever releasing the original. 20000 calls grew
/// memory by 36 to 41 pages; a handler closure passed to `ob_start` (the way this was found)
/// leaked the same way, through `ob_end_flush` too.
#[test]
fn test_cli_wasm_returning_a_built_string_does_not_leak_the_original() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_return_built_string");
    let (out, grew) = wasm_audit_run(
        &dir,
        "retleak.php",
        r#"<?php
function a($b) { return str_repeat('a', 100); }
function c(string $b) { return $b . "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"; }
$n = 0;
for ($i = 0; $i < 20000; $i++) {
    $n += strlen(a("x")) + strlen(c("y"));
    c("z");
}
echo $n, "\n";
"#,
    );
    assert_eq!(out, "3060000\n");
    assert!(grew <= 2, "a returned built string leaked its original block: {grew} pages");

    for (name, finish) in [("flush", "ob_end_flush();"), ("clean", "ob_end_clean();")] {
        let (_, grew) = wasm_audit_run(
            &dir,
            &format!("obhandler_{name}.php"),
            &format!(
                "<?php\nfor ($i = 0; $i < 20000; $i++) {{\n    ob_start(function ($b) {{ return str_repeat('a', 100); }});\n    echo \"x\";\n    {finish}\n}}\necho \"done\\n\";\n"
            ),
        );
        assert!(grew <= 2, "an ob_start handler returning str_repeat leaked ({name}): {grew} pages");
    }
    let _ = fs::remove_dir_all(&dir);
}

/// `ob_get_status()` reports the flag bits and the buffer size php keeps: STARTED|PROCESSED
/// (0x5000) join `flags` once the handler has run, `buffer_size` starts from the chunk size and
/// grows with the bytes appended by php's own rule (16384 -> 32768 when the free space is not
/// larger than a write). Every row is php 8.5's own output for the same script.
#[test]
fn test_cli_wasm_ob_get_status_tracks_flags_and_buffer_growth() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_ob_status_growth");
    let (out, _) = wasm_audit_run(
        &dir,
        "obstatus2.php",
        r#"<?php
ob_start(function ($b) { return $b; }, 3);
echo "abcd";
$a = ob_get_status();
echo str_repeat("x", 5000);
$b = ob_get_status();
ob_end_clean();
ob_start(function ($b) { return $b; });
echo str_repeat("x", 5000);
$b2 = ob_get_status();
echo str_repeat("x", 12000);
$c = ob_get_status();
ob_end_clean();
ob_start();
echo "q";
$e = ob_get_status();
echo str_repeat("y", 20000);
$f = ob_get_status();
ob_end_clean();
foreach ([$a, $b, $b2, $c, $e, $f] as $s) {
    echo $s['type'], ",", $s['flags'], ",", $s['level'], ",", $s['chunk_size'], ",", $s['buffer_size'], ",", $s['buffer_used'], "\n";
}
"#,
    );
    let expected = format!(
        "abcd{}1,20593,0,3,4096,0\n1,20593,0,3,8192,0\n1,113,0,0,16384,5000\n1,113,0,0,32768,17000\n0,112,0,0,16384,1\n0,112,0,0,32768,20001\n",
        "x".repeat(5000)
    );
    assert_eq!(out, expected);
    let _ = fs::remove_dir_all(&dir);
}

/// Returning a string read from a static property handed the CALLER the slot's own block, so the
/// caller's release freed the property's string: `Box::$last = $a . "!"; return Box::$last;` left
/// `Box::$last` reading as blanks. The return now gives the caller a private copy. The same
/// shapes through a static local, an instance property, and the array and object variants of each
/// already kept their reference and are pinned here too; the loop proves the copy is released.
#[test]
fn test_cli_wasm_returning_a_static_property_string_keeps_the_slot_alive() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_return_static_slot");
    let (out, _) = wasm_audit_run(
        &dir,
        "staticret.php",
        r##"<?php
class Obj { public $v = 0; }
class Box {
    public static string $last = "";
    public static array $arr = [];
    public static ?Obj $obj = null;
    public string $p = "";
    public array $pa = [];
    public ?Obj $po = null;
    function setp(string $a): string { $this->p = $a . "!"; return $this->p; }
    function seta(int $n): array { $this->pa = [$n, $n + 1]; return $this->pa; }
    function seto(): Obj { $t = new Obj(); $t->v = 5; $this->po = $t; return $this->po; }
}
function statv(string $a): string { Box::$last = $a . "!"; return Box::$last; }
function stata(int $n): array { Box::$arr = [$n, $n + 1]; return Box::$arr; }
function stato(): Obj { $t = new Obj(); $t->v = 7; Box::$obj = $t; return Box::$obj; }
function sl(string $a): string { static $s = ""; $s = $a . "#"; return $s; }
function sla(int $n): array { static $sa = []; $sa = [$n, $n]; return $sa; }
$x = statv("ab");
echo "[", $x, "] [", Box::$last, "]\n";
$x = statv("cd");
echo "[", $x, "] [", Box::$last, "]\n";
$b = new Box();
$s = $b->setp("ef");
echo "[", $s, "] [", $b->p, "]\n";
$y = $b->seta(3);
echo count($y), count($b->pa), $b->pa[1], "\n";
$z = $b->seto();
echo $z->v, $b->po->v, "\n";
$y = stata(4);
echo count($y), Box::$arr[1], "\n";
$o = stato();
echo $o->v, Box::$obj->v, "\n";
$s = sl("gh");
echo "[", $s, "]\n";
$s = sl("ij");
echo "[", $s, "]\n";
$y = sla(2);
$y = sla(3);
echo count($y), $y[1], "\n";
"##,
    );
    assert_eq!(
        out,
        "[ab!] [ab!]\n[cd!] [cd!]\n[ef!] [ef!]\n224\n55\n25\n77\n[gh#]\n[ij#]\n23\n"
    );

    let (out, grew) = wasm_audit_run(
        &dir,
        "staticretleak.php",
        r##"<?php
class Box { public static string $last = ""; }
function statv(string $a): string { Box::$last = $a . "!"; return Box::$last; }
function sl(string $a): string { static $s = ""; $s = $a . "#"; return $s; }
$n = 0;
for ($i = 0; $i < 20000; $i++) { $n += strlen(statv("ab")) + strlen(sl("cd")); }
echo $n, " ", Box::$last, "\n";
"##,
    );
    assert_eq!(out, "120000 ab!\n");
    assert!(grew <= 2, "returning a static string leaked its copy: {grew} pages");
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies a `json_encode()` called from inside `jsonSerialize()` leaves the outer encode intact.
///
/// The encoder keeps one growing buffer in module globals. A nested call used to reset the
/// length and write over the outer call's bytes, so `json_encode(new A())` printed `1"1"`
/// and a list holding it printed `1"1",2]`. php answers `"1"` and `["1",2]`.
#[test]
fn test_cli_wasm_json_encode_nested_in_json_serialize_keeps_the_outer_buffer() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_json_nested");
    let source = r#"<?php
class A implements JsonSerializable {
    public function jsonSerialize(): mixed { return json_encode(1); }
}
class B implements JsonSerializable {
    public function jsonSerialize(): mixed { return json_encode(str_repeat("x", 300)); }
}
echo json_encode(new A()), "\n";
echo json_encode([new A(), 2]), "\n";
echo strlen(json_encode([1, new B(), new B(), 3])), "\n";
echo json_encode(["k" => new A(), "z" => [new A()]]), "\n";
echo json_encode(1), "\n";
"#;
    let (stdout, _) = wasm_audit_run(&dir, "main.php", source);
    let php = Command::new("php").arg("-n").arg(dir.join("main.php")).output();
    if let Ok(php) = php {
        if php.status.success() {
            assert_eq!(stdout, String::from_utf8_lossy(&php.stdout), "php-src disagrees");
        }
    }
    assert_eq!(
        stdout,
        "\"1\"\n[\"1\",2]\n619\n{\"k\":\"1\",\"z\":[\"1\"]}\n1\n"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies output a handler produces while it runs is discarded instead of re-entering it.
///
/// With a chunk size of 1, an `echo` inside the handler appended to the buffer being flushed
/// and flushed it again from inside the handler until the host stack overflowed. php 8.5
/// discards that output (and raises a deprecation this target does not print).
#[test]
fn test_cli_wasm_output_handler_echo_is_discarded() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_ob_handler_echo");
    let source = r#"<?php
ob_start(function(string $b): string { echo 'side'; return "[" . $b . "]"; }, 1);
echo 'x';
echo 'y';
ob_end_flush();
echo "\nend\n";
"#;
    let (stdout, _) = wasm_audit_run(&dir, "main.php", source);
    assert_eq!(stdout, "[x][y][]\nend\n");
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies a `jsonSerialize()` that answers `$this` encodes the properties, and that two
/// objects answering each other end at the depth limit.
///
/// Encoding the answer of `return $this;` called the method again until the host stack
/// overflowed; php reads it as a request for the property walk. A cycle through two different
/// objects' `jsonSerialize()` has no such escape, and php answers `false` for it.
#[test]
fn test_cli_wasm_json_serialize_returning_this_encodes_the_properties() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_json_serialize_this");
    let source = r#"<?php
class P implements JsonSerializable {
    public int $a = 1;
    public string $b = "x";
    public function jsonSerialize(): mixed { return $this; }
}
class A implements JsonSerializable {
    public ?B $b = null;
    public function jsonSerialize(): mixed { return $this->b; }
}
class B implements JsonSerializable {
    public ?A $a = null;
    public function jsonSerialize(): mixed { return $this->a; }
}
echo json_encode(new P()), "\n";
echo json_encode([new P(), 2]), "\n";
$a = new A(); $b = new B(); $a->b = $b; $b->a = $a;
$r = json_encode($a); if ($r === false) { echo "false\n"; } else { echo $r, "\n"; }
"#;
    let (stdout, _) = wasm_audit_run(&dir, "main.php", source);
    let php = Command::new("php").arg("-n").arg(dir.join("main.php")).output();
    if let Ok(php) = php {
        if php.status.success() {
            assert_eq!(stdout, String::from_utf8_lossy(&php.stdout), "php-src disagrees");
        }
    }
    assert_eq!(stdout, "{\"a\":1,\"b\":\"x\"}\n[{\"a\":1,\"b\":\"x\"},2]\nfalse\n");
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies `json_encode()` answers `false` for a string that is not valid UTF-8.
///
/// php rejects bad lead bytes, truncated sequences, overlong forms, surrogates and points
/// above U+10FFFF with `JSON_ERROR_UTF8`; this encoder used to substitute U+FFFD or decode the
/// overlong form into a different character. A valid multibyte string must keep encoding.
#[test]
fn test_cli_wasm_json_encode_rejects_invalid_utf8_like_php() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_json_utf8");
    let source = r#"<?php
function t($v) { $r = json_encode($v); if ($r === false) { echo "false\n"; } else { echo $r, "\n"; } }
t(chr(255));
t("a\xC0\x80b");
t("\xED\xA0\x80");
t("\xF4\x90\x80\x80");
t("\xE0\x80\xAF");
t("ab\xC3");
t("\x80");
t(["k" => chr(255)]);
t([1, "ok", "bad\xFF"]);
t("é");
t("€x");
t("😀");
"#;
    let (stdout, _) = wasm_audit_run(&dir, "main.php", source);
    let php = Command::new("php").arg("-n").arg(dir.join("main.php")).output();
    if let Ok(php) = php {
        if php.status.success() {
            assert_eq!(stdout, String::from_utf8_lossy(&php.stdout), "php-src disagrees");
        }
    }
    assert_eq!(
        stdout,
        "false\nfalse\nfalse\nfalse\nfalse\nfalse\nfalse\nfalse\nfalse\n\"\\u00e9\"\n\"\\u20acx\"\n\"\\ud83d\\ude00\"\n"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies compiling a source with a 240-character stem finishes and publishes the module.
///
/// Staging names used to repeat the whole destination name, overflowing the 255-byte file-name
/// limit; the probe loop then retried the resulting error forever. The compile runs under a
/// deadline so a regression fails the test instead of hanging the suite.
#[test]
fn test_cli_wasm_long_source_stem_compiles_without_hanging() {
    let dir = make_cli_test_dir("elephc_cli_wasm_long_stem");
    let stem = "a".repeat(240);
    let php_path = dir.join(format!("{stem}.php"));
    fs::write(&php_path, "<?php\necho \"long\\n\";\n").unwrap();

    let mut child = elephc_cli_command(&dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(&php_path)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
        .expect("failed to spawn the compiler");
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(60);
    let status = loop {
        if let Some(status) = child.try_wait().unwrap() {
            break status;
        }
        if std::time::Instant::now() > deadline {
            let _ = child.kill();
            let _ = child.wait();
            panic!("compiling a 240-character stem did not finish within 60s");
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    };
    assert!(status.success(), "the long-stem compile failed");
    assert!(dir.join(format!("{stem}.wasm")).is_file());
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies `json_encode()` of INF and NAN answers `false`, as php does (JSON_ERROR_INF_OR_NAN).
#[test]
fn test_cli_wasm_json_encode_rejects_non_finite_floats() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_json_nonfinite");
    let source = r#"<?php
function t($v) { $r = json_encode($v); if ($r === false) { echo "false\n"; } else { echo $r, "\n"; } }
t(INF);
t(-INF);
t([1.5, NAN]);
t(1.5);
t(0.1);
"#;
    let (stdout, _) = wasm_audit_run(&dir, "main.php", source);
    assert_eq!(stdout, "false\nfalse\nfalse\n1.5\n0.1\n");
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies objects encode like php: dynamic properties follow the declared ones, a backed enum
/// is its value and a pure enum fails, a runtime subclass keeps its float property, and a cyclic
/// or over-deep graph answers `false` instead of overflowing the host stack.
#[test]
fn test_cli_wasm_json_encode_objects_match_php() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_json_objects");
    let source = r#"<?php
function t($v) { $r = json_encode($v); if ($r === false) { echo "false\n"; } else { echo $r, "\n"; } }
#[AllowDynamicProperties] class C { public int $a = 5; }
$c = new C(); $c->x = 1; $c->y = "s";
t($c);
echo count(get_object_vars($c)), "\n";
$o = new stdClass; $o->k = [1, 2];
t($o);
t(new stdClass);
enum E: int { case A = 1; case B = 2; }
enum S: string { case X = "x"; }
enum P { case Q; }
t(E::A); t([E::A, E::B]); t(S::X); t(P::Q); t([P::Q]);
class B {}
class D extends B { public float $x = 1.5; public int $y = 2; }
function encode(B $b): mixed { return json_encode($b); }
echo encode(new D()), "\n";
class Node { public mixed $next = null; public int $v = 1; }
$n = new Node(); $n->next = $n;
t($n);
function chain(int $n): Node {
    $h = new Node();
    for ($i = 0; $i < $n; $i++) { $m = new Node(); $m->next = $h; $h = $m; }
    return $h;
}
t(chain(600));
echo strlen(json_encode(chain(100))), "\n";
"#;
    let (stdout, _) = wasm_audit_run(&dir, "main.php", source);
    let php = Command::new("php").arg("-n").arg(dir.join("main.php")).output();
    if let Ok(php) = php {
        if php.status.success() {
            assert_eq!(stdout, String::from_utf8_lossy(&php.stdout), "php-src disagrees");
        }
    }
    assert_eq!(
        stdout,
        concat!(
            "{\"a\":5,\"x\":1,\"y\":\"s\"}\n3\n{\"k\":[1,2]}\n{}\n",
            "1\n[1,2]\n\"x\"\nfalse\nfalse\n",
            "{\"x\":1.5,\"y\":2}\n",
            "false\nfalse\n1519\n",
        )
    );
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies a class with a typed property that may stay uninitialized is refused by name for
/// `json_encode` and `get_object_vars`, since php skips the property and this target cannot tell
/// the zeroed slot from a real value.
#[test]
fn test_cli_wasm_json_encode_refuses_a_possibly_uninitialized_typed_property() {
    for (name, body) in [
        ("json", "echo json_encode($c), \"\\n\";"),
        ("vars", "echo count(get_object_vars($c)), \"\\n\";"),
    ] {
        let dir = make_cli_test_dir(&format!("elephc_cli_wasm_json_uninit_{name}"));
        let php_path = dir.join("main.php");
        fs::write(
            &php_path,
            format!("<?php\nclass C {{ public int $x; }}\n$c = new C();\n{body}\n"),
        )
        .unwrap();
        let output = elephc_cli_command(&dir)
            .arg("--target")
            .arg("wasm32-wasi")
            .arg(&php_path)
            .output()
            .expect("failed to run the compiler");
        assert!(!output.status.success(), "{name}: the shape must be refused");
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            stderr.contains("get_object_vars") || stderr.contains("json_encode"),
            "{name}: the refusal must name the call: {stderr}"
        );
        let _ = fs::remove_dir_all(&dir);
    }
}

/// Verifies a loop of `json_encode()` calls does not grow memory: the encoder used to persist
/// its buffer and then box a second copy, stranding one block per call.
#[test]
fn test_cli_wasm_json_encode_does_not_leak_per_call() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_json_leak");
    let source = r#"<?php
$n = 0;
for ($i = 0; $i < 20000; $i++) {
    $n += strlen(json_encode([$i, "x"]));
}
echo $n > 0 ? "ok" : "no", "\n";
"#;
    let (stdout, grew) = wasm_audit_run(&dir, "main.php", source);
    assert_eq!(stdout, "ok\n");
    assert!(grew <= 4, "20000 json_encode calls grew memory by {grew} pages");
    let _ = fs::remove_dir_all(&dir);
}

/// php formats `microtime()` from microseconds, so the last two of its eight fractional digits
/// are always `00`, and `microtime(true)` has microsecond granularity. The target used to print
/// nanoseconds divided by ten.
///
/// The host clock is replaced by one that answers a fixed nanosecond count with a non-zero
/// sub-microsecond part, because a real host may only ever answer whole microseconds.
#[test]
fn test_cli_wasm_microtime_has_microsecond_granularity() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_microtime_us");
    let path = dir.join("microtime.php");
    fs::write(
        &path,
        r##"<?php
echo microtime(), "\n";
echo round((microtime(true) - 1789824612) * 1000000), "\n";
"##,
    )
    .unwrap();
    let built = elephc_cli_command(&dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(&path)
        .output()
        .expect("failed to invoke elephc");
    assert!(built.status.success(), "{}", String::from_utf8_lossy(&built.stderr));
    let runner = dir.join("run_clock.mjs");
    fs::write(
        &runner,
        r#"import { readFileSync } from "node:fs";
import { WASI } from "node:wasi";
const wasi = new WASI({ version: "preview1", args: ["m"], env: {}, returnOnExit: true });
const imports = wasi.getImportObject();
let instance;
imports.wasi_snapshot_preview1.clock_time_get = (id, precision, out) => {
  new DataView(instance.exports.memory.buffer).setBigUint64(out, 1789824612123456789n, true);
  return 0;
};
instance = await WebAssembly.instantiate(await WebAssembly.compile(readFileSync(process.argv[2])), imports);
process.exitCode = wasi.start(instance);
"#,
    )
    .unwrap();
    let run = node_command()
        .arg("--no-warnings")
        .arg(&runner)
        .arg(dir.join("microtime.wasm"))
        .current_dir(&dir)
        .output()
        .expect("failed to run under Node");
    assert!(run.status.success(), "{}", String::from_utf8_lossy(&run.stderr));
    // php prints microseconds times one hundred: 123456789 ns is 123456 us.
    assert_eq!(
        String::from_utf8_lossy(&run.stdout),
        "0.12345600 1789824612\n123456\n"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// `array_unique` over integers keeps the first occurrence and the original keys, whatever the
/// values (negative, zero, the extremes). Membership used to be a scan of every earlier element,
/// which made `array_unique(range(1, 100000))` about five billion comparisons.
#[test]
fn test_cli_wasm_array_unique_ints_uses_a_membership_table() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_array_unique_table");
    let (out, _) = wasm_audit_run(
        &dir,
        "unique.php",
        r##"<?php
$a = [5, -3, 5, 0, -3, 7, 9, 7, PHP_INT_MAX, PHP_INT_MIN, PHP_INT_MAX, 0];
echo json_encode(array_unique($a)), "\n";
echo implode(",", array_keys(array_unique($a))), "\n";
echo count(array_unique(range(1, 100000))), "\n";
echo count(array_unique([])), count(array_unique([4])), "\n";
"##,
    );
    // Measured on php 8.5.
    assert_eq!(
        out,
        "{\"0\":5,\"1\":-3,\"3\":0,\"5\":7,\"6\":9,\"8\":9223372036854775807,\"9\":-9223372036854775808}\n0,1,3,5,6,8,9\n100000\n01\n"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// An inner buffer forwarding into a chunked outer one must trip the outer chunk check, as php
/// does: the bytes used to reach the outer level through the bare append and skip it.
#[test]
fn test_cli_wasm_nested_output_buffer_forwarding_honours_the_outer_chunk_size() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_ob_nested_chunk");
    let (out, _) = wasm_audit_run(
        &dir,
        "obchunk.php",
        r##"<?php
class C { public static int $n = 0; }
ob_start(function(string $s, int $p): string { C::$n++; return $s; }, 1);
ob_start(function(string $s, int $p): string { return $s; }, 1);
echo "a"; echo "b";
ob_end_clean();
$n = C::$n;
ob_end_clean();
echo $n, "\n";
"##,
    );
    assert_eq!(out, "ab2\n");
    let _ = fs::remove_dir_all(&dir);
}

/// `ob_get_status()` built its hash at refcount 1 and then boxed it, which takes a second
/// reference; the constructor's was never dropped, on either return path, so every call leaked
/// a whole status hash (1516 pages over 80000 calls).
#[test]
fn test_cli_wasm_ob_get_status_does_not_leak() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_ob_status_leak");
    let (out, grew) = wasm_audit_run(
        &dir,
        "obstatus.php",
        r##"<?php
for ($i = 0; $i < 80000; $i++) { $e = ob_get_status(); }
ob_start();
for ($i = 0; $i < 80000; $i++) { $s = ob_get_status(); }
ob_end_clean();
echo count($e), count($s), " ", $s["name"], " ", $s["level"], "\n";
"##,
    );
    assert_eq!(out, "07 default output handler 0\n");
    assert!(grew <= 2, "ob_get_status leaked: {grew} pages");
    let _ = fs::remove_dir_all(&dir);
}

/// A first-class-callable wrapper over a function with a string parameter persists a private
/// copy of the argument; only the closure wrapper gave it back, so every `array_map($f, ...)`
/// through `length(...)` leaked one string. Both wrapper builders now share the cleanup, and a
/// body returning its parameter must not free the aliased copy twice.
#[test]
fn test_cli_wasm_first_class_callable_string_param_does_not_leak() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_fcc_string_leak");
    let (out, grew) = wasm_audit_run(
        &dir,
        "fccleak.php",
        r##"<?php
function length(string $s): int { return strlen($s); }
function same(string $s): string { return $s; }
$f = length(...);
$g = same(...);
$a = ["x"];
for ($i = 0; $i < 80000; $i++) { array_map($f, $a); array_map($g, $a); }
echo array_map($g, ["ab", "cd"])[1], array_map($f, ["abc"])[0], "\n";
"##,
    );
    assert_eq!(out, "cd3\n");
    assert!(grew <= 2, "the first-class callable wrapper leaked its string copy: {grew} pages");
    let _ = fs::remove_dir_all(&dir);
}

/// Compiles `source` for `wasm32-wasi`, runs it under Node and answers `(stdout, stderr, exit
/// code)` without requiring success, for programs that are EXPECTED to stop on a named fatal.
fn wasm_audit_run_to_fatal(
    dir: &std::path::Path,
    name: &str,
    source: &str,
) -> (String, String, Option<i32>) {
    let runner = dir.join("run_fatal.mjs");
    fs::write(
        &runner,
        r#"import { readFileSync } from "node:fs";
import { WASI } from "node:wasi";
const wasi = new WASI({ version: "preview1", args: ["m"], env: {}, returnOnExit: true, preopens: { ".": "." } });
const instance = await WebAssembly.instantiate(
  await WebAssembly.compile(readFileSync(process.argv[2])),
  wasi.getImportObject(),
);
process.exitCode = wasi.start(instance);
"#,
    )
    .unwrap();
    let path = dir.join(name);
    fs::write(&path, source).unwrap();
    let built = elephc_cli_command(dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(&path)
        .output()
        .expect("failed to invoke elephc");
    assert!(
        built.status.success(),
        "{name} failed to compile: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let stem = name.trim_end_matches(".php");
    let run = node_command()
        .arg("--no-warnings")
        .arg(&runner)
        .arg(dir.join(format!("{stem}.wasm")))
        .current_dir(dir)
        .output()
        .expect("failed to run under Node");
    (
        String::from_utf8_lossy(&run.stdout).to_string(),
        String::from_utf8_lossy(&run.stderr).to_string(),
        run.status.code(),
    )
}

/// An in-memory stream whose write position plus length cannot be represented must stop on the
/// allocator's named out-of-memory fatal. The capacity used to be doubled in i64 and narrowed
/// with `i32.wrap_i64`, so `fseek($h, 2147483648); fwrite($h, "x")` asked for a 2^32-byte
/// capacity that wrapped to ZERO and the copy loop then wrote past a tiny block.
#[test]
fn test_cli_wasm_memory_stream_growth_overflow_is_a_named_fatal() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_memstream_overflow");
    for (name, seek) in [("ms_a.php", "2147483648"), ("ms_b.php", "PHP_INT_MAX")] {
        let (stdout, stderr, code) = wasm_audit_run_to_fatal(
            &dir,
            name,
            &format!(
                "<?php\n$h = fopen(\"php://temp\", \"w+\");\nfseek($h, {seek});\nfwrite($h, \"xy\");\necho \"reached\\n\";\n"
            ),
        );
        assert_eq!(stdout, "", "{name}: the write must not complete");
        assert!(
            stderr.contains("PHP Fatal error: Allowed memory size exhausted"),
            "{name}: expected the named out-of-memory fatal, got: {stderr}"
        );
        assert_eq!(code, Some(255), "{name}: a clean fatal exits 255, not a trap: {stderr}");
    }
    // A stream well inside the ceiling still grows normally past a seek.
    let (out, _) = wasm_audit_run(
        &dir,
        "ms_ok.php",
        "<?php\n$h = fopen(\"php://temp\", \"w+\");\nfseek($h, 100000);\nfwrite($h, \"x\");\nrewind($h);\necho strlen(stream_get_contents($h)), \"\\n\";\n",
    );
    assert_eq!(out, "100001\n");
    let _ = fs::remove_dir_all(&dir);
}

/// A line longer than 1 MiB used to come back from `fscanf` as a TRUNCATED success, with the next
/// byte already consumed. The reader now keeps doubling its buffer, so the whole line is one
/// field and the following line is intact.
#[test]
fn test_cli_wasm_fscanf_reads_a_line_past_one_mebibyte() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_fscanf_long_line");
    let mut data = "x".repeat(1_500_000);
    data.push_str("\nsecond 7\n");
    fs::write(dir.join("big.txt"), data).unwrap();
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "longline.php",
        r##"<?php
$h = fopen("big.txt", "r");
$a = fscanf($h, "%s");
echo strlen($a[0]), "\n";
$b = fscanf($h, "%s %s");
echo $b[0], $b[1], "\n";
"##,
    );
    assert_eq!(code, Some(0), "stderr: {stderr}");
    assert_eq!(stdout, "1500000\nsecond7\n");
    let _ = fs::remove_dir_all(&dir);
}

/// A directory whose snapshot is larger than 1 MiB used to be treated as complete at the cap, so
/// `readdir` silently stopped partway. The snapshot now keeps growing until the listing fits.
#[test]
fn test_cli_wasm_readdir_lists_a_directory_past_one_mebibyte_of_dirents() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_readdir_large");
    let many = dir.join("many");
    fs::create_dir(&many).unwrap();
    // Each dirent is 24 bytes of header plus the name, so 30,000 names of 40 bytes pass 1.9 MiB.
    for i in 0..30_000u32 {
        fs::write(many.join(format!("file_with_a_long_enough_name_{i:010}")), "").unwrap();
    }
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "bigdir.php",
        r##"<?php
$d = opendir("many");
$n = 0;
while (($e = readdir($d)) !== false) { $n++; }
closedir($d);
echo $n, "\n";
"##,
    );
    assert_eq!(code, Some(0), "stderr: {stderr}");
    // 30,000 files plus the `.` and `..` php always reports.
    assert_eq!(stdout, "30002\n");
    let _ = fs::remove_dir_all(&dir);
}

/// `spl_object_id()` and the release of an object's handle found the slot by scanning the whole
/// pool, which is quadratic over many live objects. A reverse index (address to slot, with
/// tombstones and rebuilds) replaced the scan; the ids themselves must be exactly the ones php
/// hands out, including LIFO reuse and ids that survive heavy allocate/free churn.
///
/// Expected output is php 8.5's own.
#[test]
fn test_cli_wasm_object_handles_survive_churn_and_scale() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_object_handle_index");
    let (out, _) = wasm_audit_run(
        &dir,
        "handles.php",
        r##"<?php
class A { public $v; function __construct($v = 0) { $this->v = $v; } }
$a = new A(); $b = new A(); echo spl_object_id($a), spl_object_id($b), "\n";
unset($a); $c = new A(); echo spl_object_id($c), "\n";
$keep = []; $churn = [];
for ($i = 0; $i < 3000; $i++) { $keep[] = new A($i); $churn[] = new A($i); }
$sum = 0;
foreach ($keep as $o) { $sum += spl_object_id($o); }
echo $sum, "\n";
for ($r = 0; $r < 20; $r++) {
  $churn = [];
  for ($i = 0; $i < 3000; $i++) { $churn[] = new A($i); }
}
$s2 = 0; foreach ($churn as $o) { $s2 += spl_object_id($o); }
echo $s2, "\n";
$s3 = 0; foreach ($keep as $o) { $s3 += spl_object_id($o); }
echo $s3, " ", spl_object_id($b), " ", spl_object_id($c), "\n";
$many = [];
for ($i = 0; $i < 60000; $i++) { $many[] = new A($i); }
$s4 = 0;
foreach ($many as $o) { $s4 += spl_object_id($o); }
echo $s4 > 0 ? "many ok" : "many bad", "\n";
$many = null;
"##,
    );
    assert_eq!(out, "12\n1\n9006000\n9009000\n9006000 2 1\nmany ok\n");
    let _ = fs::remove_dir_all(&dir);
}

/// A `foreach` over a generator is php's REWIND: a generator already sitting at its first yield
/// shows that value, one advanced past it raises `Cannot rewind a generator that was already
/// run`, and a finished one raises `Cannot traverse an already closed generator`. The loop used
/// to resume the body unconditionally on its first step, so a primed generator lost its first
/// value and a finished or advanced one was walked silently.
///
/// Expected output is php 8.5's own.
#[test]
fn test_cli_wasm_foreach_over_a_primed_generator_rewinds_like_php() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_foreach_generator_rewind");
    let (out, _) = wasm_audit_run(
        &dir,
        "genrewind.php",
        r##"<?php
function g() { yield 1; yield 2; }
$g = g(); $g->rewind(); foreach ($g as $v) { echo $v; } echo "\n";
$h = g(); echo $h->current(); foreach ($h as $v) { echo $v; } echo "\n";
foreach (g() as $v) { echo $v; } echo "\n";
$k = g(); foreach ($k as $v) { echo $v; break; } foreach ($k as $v) { echo $v; } echo "\n";
$m = g(); $m->next();
try { foreach ($m as $v) { echo $v; } } catch (Exception $e) { echo get_class($e), ":", $e->getMessage(), "\n"; }
$n = g();
foreach ($n as $v) { if ($v == 2) { break; } }
try { foreach ($n as $v) { echo $v; } } catch (Exception $e) { echo $e->getMessage(), "\n"; }
$c = g(); foreach ($c as $v) {}
try { foreach ($c as $v) { echo $v; } } catch (Exception $e) { echo $e->getMessage(), "\n"; }
function e() { return; yield; }
$z = e(); foreach ($z as $v) { echo "never"; } echo "empty ok\n";
try { foreach ($z as $v) { echo "never"; } } catch (Exception $e) { echo $e->getMessage(), "\n"; }
"##,
    );
    assert_eq!(
        out,
        "12\n112\n12\n112\nException:Cannot rewind a generator that was already run\n\
         Cannot rewind a generator that was already run\n\
         Cannot traverse an already closed generator\nempty ok\n\
         Cannot traverse an already closed generator\n"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// A generator closure that captures a CALLABLE kept the descriptor as a bare word in its frame:
/// callable descriptors travel in an `I64` carrier, and the wrapper only retained `Heap(_)` and
/// string arguments. Once the creator dropped the closure the frame held a dangling descriptor,
/// and the first call through it died with `Invalid callable dispatch`.
///
/// The wrapper now retains the descriptor, the body's epilogue gives it back on completion, and
/// a frame dropped while suspended releases it too; the loops below fail to stay flat if either
/// release is missing. (A bare `yield $cb();` is deliberately not used in the loops: that shape
/// leaks its result cell for a reason unrelated to the capture.)
#[test]
fn test_cli_wasm_generator_closure_retains_a_captured_callable() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_generator_callable_capture");
    let (out, grew) = wasm_audit_run(
        &dir,
        "gencallable.php",
        r##"<?php
$f = fn(): int => 7;
$make = function() use ($f) { yield $f(); };
$g = $make();
unset($make, $f);
echo $g->current(), "\n";

$f2 = fn(): int => 12;
$make2 = function() use ($f2) { yield $f2(); yield $f2(); };
foreach ($make2() as $v) { echo $v; }
echo "\n";

function abandoned(int $i): int {
    $cb = fn(): int => 5;
    $mk = function() use ($cb) { $x = $cb(); yield $x; yield 2; };
    $gg = $mk();
    return $gg->current() + $i - $i;
}
function completed(int $i): int {
    $cb = fn(): int => 1;
    $mk = function() use ($cb) { $x = $cb(); yield $x; };
    $t = 0;
    foreach ($mk() as $v) { $t += $v; }
    return $t + $i - $i;
}
$n = 0; $m = 0;
for ($i = 0; $i < 80000; $i++) { $n += abandoned($i); $m += completed($i); }
echo $n, " ", $m, "\n";
"##,
    );
    assert_eq!(out, "7\n1212\n400000 80000\n");
    assert!(grew <= 2, "a generator frame leaked its captured callable: {grew} pages");
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies `fread` on an opened file: a short read sets EOF as php's plain-file stream does,
/// and a length past what the module can allocate is php's memory-limit fatal.
///
/// The count was narrowed to 32 bits before anything looked at it, so `fread($h, 2**32 + 1)`
/// read one byte and `fread($h, 2**32)` read none and flagged EOF. php allocates the length
/// up front and stops with "Allowed memory size ... exhausted".
#[test]
fn test_cli_wasm_fread_checks_its_length_and_flags_a_short_read() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_fread_length");
    let source = r#"<?php
$f = fopen("data.txt", "w");
fwrite($f, "hello");
fclose($f);
$f = fopen("data.txt", "r");
echo strlen(fread($f, 3)), "\n";
echo fread($f, 10), "|", feof($f) ? "eof" : "more", "\n";
fclose($f);
$f = fopen("data.txt", "r");
$r = fread($f, 4294967297);
echo "unreachable ", strlen($r), "\n";
"#;
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(&dir, "main.php", source);
    assert_eq!(stdout, "3\nlo|eof\n", "stderr: {stderr}");
    assert!(stderr.contains("Allowed memory size exhausted"), "{stderr}");
    assert_eq!(code, Some(255));
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies `stream_get_contents()` and `stream_copy_to_stream()` read a PIPED stdin.
///
/// Both measured the remaining length with a seek to the end, which a pipe cannot do, so they
/// answered an empty string and copied nothing. 20000 bytes cross the 4 KiB first block, and a
/// capped read takes exactly its limit before the copy drains the rest.
#[test]
fn test_cli_wasm_stream_reads_drain_a_piped_stdin() {
    if node_missing_skips_test() {
        return;
    }
    use std::io::Write as _;
    let dir = make_cli_test_dir("elephc_cli_wasm_piped_stdin");
    let source = r#"<?php
$head = stream_get_contents(STDIN, 5);
echo $head, "\n";
$out = fopen("php://memory", "w+");
echo stream_copy_to_stream(STDIN, $out), "\n";
rewind($out);
echo md5(stream_get_contents($out)), "\n";
"#;
    // Compiles it; the run below replaces this helper's run, which has no stdin.
    let _ = wasm_audit_run(&dir, "main.php", source);
    let input: String = (0..20000).map(|i| (b'a' + (i % 26) as u8) as char).collect();
    let mut child = node_command()
        .arg("--no-warnings")
        .arg(dir.join("run_audit.mjs"))
        .arg(dir.join("main.wasm"))
        .current_dir(&dir)
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
        .expect("failed to run under Node");
    child
        .stdin
        .take()
        .expect("stdin")
        .write_all(input.as_bytes())
        .expect("write stdin");
    let run = child.wait_with_output().expect("wait for Node");
    // php-src 8.5: `md5` of the 19995 bytes after the capped read.
    let tail_md5 = "27bc4f6c7a8ee117e5e9388400ad541c";
    assert_eq!(
        String::from_utf8_lossy(&run.stdout),
        format!("abcde\n19995\n{tail_md5}\n"),
        "stderr: {}",
        String::from_utf8_lossy(&run.stderr)
    );
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies the gap a write past the end of a memory stream opens reads back as zeros.
///
/// The buffer can be a reused block, and growing it copies only the live bytes, so the gap held
/// whatever that block contained: here the `Z`s of a string freed just before the write.
#[test]
fn test_cli_wasm_memory_stream_gap_is_zero_filled() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_memstream_gap");
    let source = r#"<?php
$h = fopen("php://memory", "w+");
fwrite($h, "ab");
fseek($h, 40);
$junk = str_repeat("Z", 64);
$junk = "";
fwrite($h, "cd");
rewind($h);
$s = stream_get_contents($h);
echo strlen($s), " ", bin2hex($s), "\n";
"#;
    let (stdout, _) = wasm_audit_run(&dir, "main.php", source);
    assert_eq!(stdout, format!("42 6162{}6364\n", "00".repeat(38)));
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies boxed `-1 * PHP_INT_MIN` widens to a float instead of trapping.
///
/// The overflow check divided the wrapped product by the left factor, and `INT_MIN / -1`
/// traps; `i32.or` evaluated it even though the special case beside it already answered.
#[test]
fn test_cli_wasm_boxed_multiply_of_minus_one_and_int_min_widens() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_boxed_mul_int_min");
    let source = r#"<?php
function id(mixed $x): mixed { return $x; }
$a = id(-1);
$b = id(PHP_INT_MIN);
echo $a * $b, "\n";
echo $b * $a, "\n";
echo id(3) * id(4), "\n";
"#;
    let (stdout, _) = wasm_audit_run(&dir, "main.php", source);
    assert_eq!(stdout, "9.2233720368548E+18\n9.2233720368548E+18\n12\n");
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies a stream closed through one copy of its handle is closed for every copy.
///
/// An array stores the raw handle and boxes it afresh on every read, so the -1 stamp `fclose`
/// left on its box was lost and a second `fclose($a['h'])` freed the memory-stream descriptor
/// again. php raises a `TypeError` for it.
#[test]
fn test_cli_wasm_fclose_through_an_array_copy_sees_the_closed_stream() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_fclose_array_copy");
    let source = r#"<?php
$a = ['h' => fopen('php://memory', 'w+'), 'n' => 1];
fwrite($a['h'], "abc");
echo fclose($a['h']) ? "closed\n" : "not\n";
try {
    fclose($a['h']);
    echo "closed again\n";
} catch (TypeError $e) {
    echo "TypeError: ", $e->getMessage(), "\n";
}
$x = str_repeat("Q", 40);
echo $x, "\n";
"#;
    let (stdout, _) = wasm_audit_run(&dir, "main.php", source);
    assert_eq!(
        stdout,
        "closed\nTypeError: fclose(): Argument #1 ($stream) must be an open stream resource\n\
         QQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQ\n"
    );
    let _ = fs::remove_dir_all(&dir);
}

