/// A read through a missing nullable array warns and continues; a coalescing read of a missing
/// list element stays silent.
///
/// Reaches `warn` and `array_get_silent`. php-src's CLI prints the warning on stdout and this
/// backend prints it on stderr, so the streams are checked separately.
#[test]
fn test_cli_wasm_offset_on_null_warning_and_silent_read_match_php() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_inventory_warn");
    let source = r#"<?php
function arr(int $k): ?array { return $k > 5 ? [1] : null; }
$k = $argc;
echo arr($k)[0];
echo "|";
$l = [1, 2];
echo $l[7] ?? "e", "\n";
"#;
    let (stdout, stderr, code) = wasm_inventory_run(
        &dir,
        "warn.php",
        source,
        &[Op::Warn, Op::ArrayGetSilent],
        &[],
    );
    assert_eq!(code, Some(0), "{stderr}");
    assert_eq!(stdout, "|e\n");
    assert_eq!(stderr, "Warning: Trying to access array offset on null\n");
    if let Some(php) = wasm_inventory_php_stdout(&dir, "warn.php") {
        assert!(
            php.contains("Warning: Trying to access array offset on null in ")
                && php.ends_with("|e\n"),
            "php -n disagrees: {php}"
        );
    }
    let _ = fs::remove_dir_all(&dir);
}

/// A method call on a null receiver is php-src's uncatchable-here `Error`: the output before it
/// is flushed, the process exits 255, and the diagnostic names the method.
///
/// Reaches `throw_error`.
#[test]
fn test_cli_wasm_method_call_on_null_error_matches_php() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_inventory_throw_error");
    let source = r#"<?php
class Item { public int $v = 1; public function value(): int { return $this->v; } }
function maybe(int $k): ?Item { return $k > 5 ? new Item : null; }
echo "a";
echo maybe($argc)->value();
"#;
    let (stdout, stderr, code) =
        wasm_inventory_run(&dir, "throw_error.php", source, &[Op::ThrowError], &[]);
    assert_eq!(code, Some(255), "{stderr}");
    assert_eq!(stdout, "a");
    assert!(
        stderr.contains("Uncaught Error: Call to a member function value() on null"),
        "{stderr}"
    );
    if let Some(php) = wasm_inventory_php_stdout(&dir, "throw_error.php") {
        assert!(
            php.starts_with("a\nFatal error: Uncaught Error: Call to a member function value() on null"),
            "php -n disagrees: {php}"
        );
    }
    let _ = fs::remove_dir_all(&dir);
}

