/// A `match` with no matching arm ends in the `fatal` terminator: output before it is flushed
/// and the process exits 255 like php-src's uncaught `UnhandledMatchError`.
///
/// Reaches `Terminator::Fatal`. php-src names the error class and the unmatched value; this
/// backend writes a fixed `unhandled match case`, so only the text they share is compared.
#[test]
fn test_cli_wasm_unmatched_match_is_a_fatal_like_php() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_inventory_fatal");
    let source = "<?php\n$k = $argc;\necho \"before\\n\";\necho match ($k) { 5 => \"five\", 6 => \"six\" };\necho \"after\\n\";\n";
    let (stdout, stderr, code) =
        wasm_inventory_run(&dir, "fatal.php", source, &[], &["fatal"]);
    assert_eq!(code, Some(255), "{stderr}");
    assert_eq!(stdout, "before\n");
    assert!(
        stderr.to_lowercase().contains("unhandled match case"),
        "{stderr}"
    );
    if let Some(php) = wasm_inventory_php_stdout(&dir, "fatal.php") {
        assert!(
            php.starts_with("before\n") && php.to_lowercase().contains("unhandled match case"),
            "php -n disagrees: {php}"
        );
    }
    let _ = fs::remove_dir_all(&dir);
}

