/// `function_exists` over a literal name and `ob_start` are the builtins whose lowering records
/// the call site's strictness profile (`RuntimeCallTarget::ProfiledFunction`); both produce
/// php-src's answers on WASM.
#[test]
fn test_cli_wasm_profiled_runtime_functions_match_php() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_inventory_profiled");
    wasm_inventory_expect_php_output(
        &dir,
        "profiled.php",
        r#"<?php
function helper() { return 1; }
echo function_exists("helper") ? "Y" : "N", function_exists("nope_fn") ? "Y" : "N", "\n";
ob_start();
echo "buf";
$s = ob_get_clean();
echo strtoupper($s), "\n";
"#,
        &[],
        &[],
        "YN\nBUF\n",
    );
    let _ = fs::remove_dir_all(&dir);
}

/// Closures created inside class methods compile and answer `static::` for the CALLED class.
///
/// main's lowering captures the called-class id into every closure a method creates, through
/// `Op::LoadCalledClassId`, so every such closure was refused on this target. The arrow
/// function also reads `$this`, whose boxed capture was freed while the descriptor held it
/// until a released owned capture stopped being taken over without a reference.
#[test]
fn test_cli_wasm_closures_created_in_methods_match_php() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_method_closures");
    wasm_inventory_expect_php_output(
        &dir,
        "main.php",
        r#"<?php
class C {
    public int $n = 5;
    public function who(): string { $f = function(): string { return static::class; }; return $f(); }
    public function twice(int $x): int { $g = fn(int $y): int => $y * 2 + $this->n; return $g($x); }
    public static function swho(): string { $f = function(): string { return static::class; }; return $f(); }
}
class D extends C {}
echo (new C())->who(), " ", (new D())->who(), "\n";
echo (new D())->twice(10), "\n";
echo C::swho(), " ", D::swho(), "\n";
"#,
        &[Op::LoadCalledClassId],
        &[],
        "C D\n25\nC D\n",
    );
    let _ = fs::remove_dir_all(&dir);
}

/// An output-buffer operation called from inside an output handler is php's non-catchable fatal
/// `ob_X(): Cannot use output buffering in output buffering display handlers`. It used to recurse
/// until the host stack overflowed, because `ob_end_clean` ran the handler again.
#[test]
fn test_cli_wasm_ob_operations_inside_a_handler_are_php_fatals() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_ob_in_handler");
    for (index, call) in ["ob_end_clean()", "ob_end_flush()", "ob_get_clean()", "ob_start()"]
        .iter()
        .enumerate()
    {
        let (stdout, stderr, code) = wasm_audit_run_to_fatal(
            &dir,
            &format!("obh{index}.php"),
            &format!(
                "<?php\necho \"a\";\nob_start(function(string $s, int $p): string {{ {call}; return $s; }}, 1);\necho \"x\";\n"
            ),
        );
        let name = call.trim_end_matches("()");
        assert_eq!(stdout, "a", "{call}: only the output before the buffer survives");
        assert!(
            stderr.contains(&format!(
                "PHP Fatal error: {name}(): Cannot use output buffering in output buffering display handlers"
            )),
            "{call}: expected php's named fatal, got: {stderr}"
        );
        assert_eq!(code, Some(255), "{call}: {stderr}");
    }
    // Read-only operations stay legal inside a handler.
    let (out, _) = wasm_audit_run(
        &dir,
        "obh_ok.php",
        "<?php\nob_start(function(string $s): string { return $s . ob_get_status()[\"level\"]; });\necho \"x\";\nob_end_flush();\n",
    );
    assert_eq!(out, "x0");
    let _ = fs::remove_dir_all(&dir);
}

/// Dynamic array callables resolve class and method names ASCII case-insensitively, and a class
/// string may carry one leading backslash, as php does. The ladders compared bytes exactly, so
/// `[new C(), "RUN"]` answered `Invalid callable dispatch`.
#[test]
fn test_cli_wasm_dynamic_array_callables_fold_name_case() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_cbarr_case");
    let (out, _) = wasm_audit_run(
        &dir,
        "cbarr.php",
        r##"<?php
class C {
    public function run(): int { return 7; }
    public static function make(): int { return 9; }
}
$name = $argc > 1 ? "run" : "RUN";
$cb = [new C(), $name];
echo $cb(), "\n";
$cls = $argc > 1 ? "C" : "\\c";
$m = $argc > 1 ? "make" : "MaKe";
$sb = [$cls, $m];
echo $sb(), "\n";
echo call_user_func([new C(), "rUn"]), "\n";
"##,
    );
    assert_eq!(out, "7\n9\n7\n");
    let _ = fs::remove_dir_all(&dir);
}

/// A `JsonSerializable` whose `jsonSerialize()` answers `$this` is walked like a plain object, so
/// a typed property php skips as uninitialized would be written as `0` by this target. The class
/// is refused by name, and so is an object reaching `json_encode` through a `mixed` value while a
/// class with such a property exists. A class whose constructor initializes the property is
/// still served.
#[test]
fn test_cli_wasm_json_encode_refuses_uninitialized_properties_behind_serializable_and_mixed() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_json_uninit");
    let err = wasm_audit_refusal(
        &dir,
        "json_this.php",
        r##"<?php
class C implements JsonSerializable {
    public int $x;
    public function jsonSerialize(): mixed { return $this; }
}
echo json_encode(new C());
"##,
    );
    assert!(err.contains("json_encode of"), "{err}");
    let err = wasm_audit_refusal(
        &dir,
        "json_mixed.php",
        r##"<?php
class P { public int $x; }
function wrap(mixed $v): string { return json_encode($v); }
echo wrap(new P());
"##,
    );
    assert!(err.contains("json_encode of"), "{err}");
    let (out, _) = wasm_audit_run(
        &dir,
        "json_ok.php",
        r##"<?php
class C implements JsonSerializable {
    public int $x;
    public function __construct() { $this->x = 4; }
    public function jsonSerialize(): mixed { return $this; }
}
echo json_encode(new C());
"##,
    );
    assert_eq!(out, "{\"x\":4}");
    let _ = fs::remove_dir_all(&dir);
}

/// `fscanf` numeric conversions are refused by name: php returns an int or a float for `%d` and
/// `%f`, and this target's `array<string>` result would answer strings (`is_int($r[0])` true in
/// php). The test used to codify the string substitutes.
#[test]
fn test_cli_wasm_fscanf_numeric_conversions_are_refused() {
    let dir = make_cli_test_dir("elephc_cli_wasm_fscanf_numeric");
    for (name, format) in [("fs_d.php", "%d"), ("fs_f.php", "%s %f")] {
        let err = wasm_audit_refusal(
            &dir,
            name,
            &format!(
                "<?php\n$f = fopen(\"php://temp\", \"w+\");\nfwrite($f, \"12 1.5\\n\");\nrewind($f);\n$r = fscanf($f, \"{format}\");\necho is_int($r[0]) ? \"int\" : \"string\";\n"
            ),
        );
        assert!(err.contains("typed int or float"), "{name}: {err}");
    }
    let _ = fs::remove_dir_all(&dir);
}

/// A generated file may not replace a file the program INCLUDES. The source-overwrite check only
/// compared outputs with the primary source, so `app.php` containing `require "app.wat";`
/// compiled for WASM replaced the included `app.wat` (a PHP file) with the generated text.
#[test]
fn test_cli_wasm_output_never_replaces_an_included_file() {
    let dir = make_cli_test_dir("elephc_cli_wasm_include_overwrite");
    let included = "<?php\necho \"lib\\n\";\n";
    fs::write(dir.join("app.wat"), included).unwrap();
    let err = wasm_audit_refusal(&dir, "app.php", "<?php\nrequire \"app.wat\";\necho \"main\\n\";\n");
    assert!(err.contains("source file this program includes"), "{err}");
    assert_eq!(fs::read_to_string(dir.join("app.wat")).unwrap(), included);
    let _ = fs::remove_dir_all(&dir);
}

/// The include bookkeeping labels (`require_once` guards, include-variant functions) must not
/// bake the absolute path of the file they came from into the module: the same project compiled
/// in two directories has to produce byte-identical WAT.
#[test]
fn test_cli_wasm_include_labels_are_independent_of_the_compile_directory() {
    let emit = |dir: &Path| -> String {
        fs::write(dir.join("lib.php"), "<?php\necho \"x\";\n").unwrap();
        fs::write(dir.join("a.php"), "<?php\nfunction pick(): int { return 1; }\n").unwrap();
        fs::write(dir.join("b.php"), "<?php\nfunction pick(): int { return 2; }\n").unwrap();
        fs::write(
            dir.join("app.php"),
            "<?php\nrequire_once \"lib.php\";\nrequire_once \"lib.php\";\nif ($argc > 5) { require \"a.php\"; } else { require \"b.php\"; }\necho \"y\", pick();\n",
        )
        .unwrap();
        let output = elephc_cli_command(dir)
            .arg("--target")
            .arg("wasm32-wasi")
            .arg("--emit-asm")
            .arg(dir.join("app.php"))
            .output()
            .expect("failed to compile to WAT");
        assert!(
            output.status.success(),
            "WAT compilation failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        fs::read_to_string(dir.join("app.wat")).expect("missing app.wat")
    };
    let first = make_cli_test_dir("elephc_cli_wasm_include_dir_first");
    let second = make_cli_test_dir("elephc_cli_wasm_include_dir_second");
    let wat_first = emit(&first);
    let wat_second = emit(&second);
    if wat_first != wat_second {
        let diff: Vec<String> = wat_first
            .lines()
            .zip(wat_second.lines())
            .filter(|(a, b)| a != b)
            .take(6)
            .map(|(a, b)| format!("- {a}\n+ {b}"))
            .collect();
        panic!("the same project compiled in two directories emitted different modules:\n{}", diff.join("\n"));
    }
    let _ = fs::remove_dir_all(&first);
    let _ = fs::remove_dir_all(&second);
}

/// `stream_get_contents` sets the end-of-file flag whenever the read ran into the end, for both
/// stream kinds: an unbounded read always does, a bounded one only when it asked for more than
/// was left. The memory stream used to advance its position without ever setting the flag, so
/// `feof` answered false after a full read.
///
/// Expected output is `php -n` 8.5's own, measured case by case.
#[test]
fn test_cli_wasm_stream_get_contents_sets_eof() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_sgc_eof");
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "main.php",
        r#"<?php
function yn($b) { return $b ? "T" : "F"; }
$h = fopen("php://memory", "r+");
fwrite($h, "ab");
rewind($h);
echo stream_get_contents($h), yn(feof($h)), " ";
rewind($h);
echo stream_get_contents($h, 1), yn(feof($h)), " ";
rewind($h);
echo stream_get_contents($h, 2), yn(feof($h)), " ";
rewind($h);
echo stream_get_contents($h, 5), yn(feof($h)), " ";
rewind($h);
echo stream_get_contents($h, 0), yn(feof($h)), " ";
echo stream_get_contents($h), yn(feof($h)), "\n";
file_put_contents("sgc_eof.txt", "abc");
$f = fopen("sgc_eof.txt", "r");
echo stream_get_contents($f), yn(feof($f)), " ";
rewind($f);
echo stream_get_contents($f, 2), yn(feof($f)), " ";
rewind($f);
echo stream_get_contents($f, 3), yn(feof($f)), "\n";
fclose($f);
unlink("sgc_eof.txt");
"#,
    );
    assert_eq!(code, Some(0), "stderr: {stderr}");
    assert_eq!(stdout, "abT aF abF abT F abT\nabcT abF abcF\n");
    let _ = fs::remove_dir_all(&dir);
}

/// The per-fd tables (eof flag, closed mark, mode/uri record, chunk size, directory state) cover
/// every fd the runtime tracks, not only the first 256. Past 255 `feof` never turned true, the
/// closed mark was lost and `stream_get_meta_data` read slot 0.
///
/// Expected output is `php -n` 8.5's own.
#[test]
fn test_cli_wasm_fd_tables_cover_descriptors_past_255() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_fd_tables_wide");
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "main.php",
        r#"<?php
file_put_contents("wide.txt", "abcdefgh");
$hs = [];
for ($i = 0; $i < 300; $i++) { $hs[] = fopen("wide.txt", "r"); }
$h = fopen("wide.txt", "r");
$n = 0;
while (!feof($h) && $n < 10) { fread($h, 8); $n++; }
echo $n, "\n";
$m = stream_get_meta_data($h);
echo $m["mode"], "|", $m["uri"], "\n";
fclose($h);
$g = fopen("wide.txt", "r");
echo ftell($g), "\n";
foreach ($hs as $x) { fclose($x); }
fclose($g);
unlink("wide.txt");
"#,
    );
    assert_eq!(code, Some(0), "stderr: {stderr}");
    assert_eq!(stdout, "2\nr|wide.txt\n0\n");
    let _ = fs::remove_dir_all(&dir);
}

/// A descriptor the host hands out past the tracked range (1024, php's usual `ulimit -n`) is
/// closed again and `fopen`/`opendir` answer `false`, as php does on `Too many open files`, so no
/// stream ever exists without its per-fd records.
#[test]
fn test_cli_wasm_descriptors_past_the_tracked_range_fail_like_emfile() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_emfile");
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "main.php",
        r#"<?php
file_put_contents("emfile.txt", "abcdefgh");
$hs = [];
$failed = 0;
for ($i = 0; $i < 1100; $i++) {
  $h = @fopen("emfile.txt", "r");
  if ($h === false) { $failed++; } else { $hs[] = $h; }
}
echo $failed > 0 ? "failed" : "none", "|", count($hs) > 1000 ? "many" : "few", "\n";
$last = $hs[count($hs) - 1];
fread($last, 100);
echo feof($last) ? "eof" : "open", "\n";
foreach ($hs as $x) { fclose($x); }
$d = opendir(".");
echo $d === false ? "nodir" : "dir", "\n";
unlink("emfile.txt");
"#,
    );
    assert_eq!(code, Some(0), "stderr: {stderr}");
    assert_eq!(stdout, "failed|many\neof\ndir\n");
    let _ = fs::remove_dir_all(&dir);
}

/// `file_exists()` (and every path stat) used to write its 64-byte result over the first 48
/// descriptors' eof flags, so `feof(STDIN)` flipped back to false.
#[test]
fn test_cli_wasm_filestat_does_not_clobber_fd_flags() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_filestat_scratch");
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "main.php",
        r#"<?php
file_put_contents("fixture.txt", "x");
fread(STDIN, 1);
echo feof(STDIN) ? "1" : "0", "|";
file_exists("fixture.txt");
echo feof(STDIN) ? "1" : "0", "\n";
unlink("fixture.txt");
"#,
    );
    assert_eq!(code, Some(0), "stderr: {stderr}");
    assert_eq!(stdout, "1|1\n");
    let _ = fs::remove_dir_all(&dir);
}

/// In-memory streams honour their open mode, as `php://memory` does: `a`/`a+` append, `w`, `w+`,
/// `r+`, `wb` and `c+` read and write, and `r`, `rb`, `x` and `c` alone are READ-ONLY — their
/// `fwrite` answers `false`. A `data:` stream is read-only too, `fseek` refuses a whence outside
/// 0/1/2 without moving, and `fprintf` still answers the formatted length for a refused write.
///
/// Expected output is `php -n` 8.5's own.
#[test]
fn test_cli_wasm_memory_stream_modes_match_php() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_memstream_modes");
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "main.php",
        r#"<?php
function yn($v) { return $v === false ? "F" : (string)$v; }
foreach (["a", "a+", "w", "r+", "x", "c", "rb", "wb", "c+"] as $m) {
  $h = fopen("php://memory", $m);
  echo $m, ":", yn(@fwrite($h, "ab")), "|";
  rewind($h);
  echo yn(@fwrite($h, "X")), "|";
  rewind($h);
  echo stream_get_contents($h), "|", ftell($h), "\n";
}
$h = fopen("php://memory", "a+"); fwrite($h, "abc"); rewind($h); echo fread($h, 1); fwrite($h, "X"); echo ftell($h), "\n";
rewind($h); echo stream_get_contents($h), "\n";
fseek($h, 1); echo fseek($h, 1, 3), "|", ftell($h), "\n";
echo fprintf(fopen("php://memory", "r"), "xy"), "\n";
$h = fopen("data:,xyz", "r"); echo yn(@fwrite($h, "q")), fread($h, 10), "\n";
"#,
    );
    assert_eq!(code, Some(0), "stderr: {stderr}");
    assert_eq!(
        stdout,
        "a:2|1|abX|3\na+:2|1|abX|3\nw:2|1|Xb|2\nr+:2|1|Xb|2\nx:F|F||0\nc:F|F||0\nrb:F|F||0\nwb:2|1|Xb|2\nc+:2|1|Xb|2\na2\nabcX\n-1|1\n2\nFxyz\n"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// `file_get_contents` and `readfile` decode a `data:` URI instead of statting it as a path, and
/// `file_put_contents` to one writes nothing (php: "Stream is not writable"). Literal `data:` paths
/// were admitted by the audit but the runtime answered `false` for every one.
///
/// Expected output is `php -n` 8.5's own.
#[test]
fn test_cli_wasm_data_uri_file_builtins_match_php() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_data_uri_files");
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "main.php",
        r#"<?php
var_dump(file_get_contents("data:text/plain,hi"));
var_dump(file_get_contents("data://text/plain;base64,SGVsbG8="));
var_dump(file_get_contents("data:,a%20b+c"));
var_dump(@file_get_contents("data:text/plain"));
var_dump(@file_get_contents("data:;BASE64,SGVsbG8="));
var_dump(readfile("data:text/plain,hey"));
var_dump(file_exists("data:text/plain,hi"));
file_put_contents("data:text/plain,hi", "x");
var_dump(file_exists("data:text/plain,hi"));
$p = "data:text/plain,dyn" . ($argc > 5 ? "x" : "");
var_dump(file_get_contents($p));
"#,
    );
    assert_eq!(code, Some(0), "stderr: {stderr}");
    assert_eq!(
        stdout,
        "string(2) \"hi\"\nstring(5) \"Hello\"\nstring(5) \"a b c\"\nbool(false)\nbool(false)\nheyint(3)\nbool(false)\nbool(false)\nstring(3) \"dyn\"\n"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// `readfile` writes through the output-buffer interception point, so `ob_start()` captures it.
/// It used to write to fd 1 directly and the bytes escaped the buffer.
#[test]
fn test_cli_wasm_readfile_goes_through_output_buffering() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_readfile_ob");
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "main.php",
        r#"<?php
file_put_contents("rf.txt", "x");
ob_start();
readfile("rf.txt");
$s = ob_get_clean();
echo "[", $s, "]\n";
unlink("rf.txt");
"#,
    );
    assert_eq!(code, Some(0), "stderr: {stderr}");
    assert_eq!(stdout, "[x]\n");
    let _ = fs::remove_dir_all(&dir);
}

/// `file_put_contents` answers `int|false` in php, but the shared contract types it `int`, so a
/// site that reads the result could not tell a failed write from an empty one. Such a site is
/// refused by name; a statement call (result unused) and a call whose result is only printed
/// still compile — printing the `0` a failed write reads as changes the text, not a decision.
#[test]
fn test_cli_wasm_file_put_contents_result_use_is_refused() {
    let dir = make_cli_test_dir("elephc_cli_wasm_fpc_result");
    let stderr = wasm_audit_refusal(
        &dir,
        "used.php",
        "<?php\n$r = file_put_contents(\"o.txt\", \"abc\");\necho $r === false ? \"false\" : \"int\", \"\\n\";\n",
    );
    assert!(stderr.contains("file_put_contents() answers int|false"), "stderr: {stderr}");
    let ok = dir.join("stmt.php");
    fs::write(
        &ok,
        "<?php\nfile_put_contents(\"o.txt\", \"abc\");\necho \"n:\", file_put_contents(\"o.txt\", \"abcd\"), \"\\n\";\n",
    )
    .unwrap();
    let built = elephc_cli_command(&dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(&ok)
        .output()
        .expect("failed to invoke elephc");
    assert!(built.status.success(), "{}", String::from_utf8_lossy(&built.stderr));
    let _ = fs::remove_dir_all(&dir);
}

/// A stream builtin handed a CLOSED handle raises php's `TypeError`, and a few length arguments
/// raise php's `ValueError`, before the builtin runs; both are catchable. Before, a read from a
/// closed copy answered `""`, `stream_get_meta_data` read freed pointers, a second `closedir`
/// closed whatever stream had been handed the recycled fd, and `fread($h, 0)` /
/// `stream_get_line($h, -5, ",")` read anyway. A `stream_get_line` cap past 2^32 no longer wraps,
/// and its delimiter must fit inside the permitted window on both stream kinds.
///
/// Expected output is `php -n` 8.5's own.
#[test]
fn test_cli_wasm_closed_handles_and_bad_lengths_raise_like_php() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_stream_guards");
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "main.php",
        r###"<?php
$h = fopen("php://memory", "w+"); $g = $h; fclose($g);
$m2 = fopen("php://memory", "w+");
try { $r0 = fread($h, 5); echo "fread: ", $r0, "\n"; } catch (Throwable $e) { echo "fread: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r1 = fwrite($h, "x"); echo "fwrite: ", $r1, "\n"; } catch (Throwable $e) { echo "fwrite: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r2 = fgetc($h); echo "fgetc: ", $r2, "\n"; } catch (Throwable $e) { echo "fgetc: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r3 = feof($h) ? "t" : "f"; echo "feof: ", $r3, "\n"; } catch (Throwable $e) { echo "feof: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r4 = ftell($h); echo "ftell: ", $r4, "\n"; } catch (Throwable $e) { echo "ftell: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r5 = rewind($h) ? "t" : "f"; echo "rewind: ", $r5, "\n"; } catch (Throwable $e) { echo "rewind: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r6 = fseek($h, 0); echo "fseek: ", $r6, "\n"; } catch (Throwable $e) { echo "fseek: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r7 = stream_get_contents($h); echo "sgc: ", $r7, "\n"; } catch (Throwable $e) { echo "sgc: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r8 = stream_get_meta_data($h)["uri"]; echo "meta: ", $r8, "\n"; } catch (Throwable $e) { echo "meta: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r9 = stream_get_line($h, 5, ","); echo "sgl: ", $r9, "\n"; } catch (Throwable $e) { echo "sgl: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r10 = flock($h, LOCK_SH) ? "t" : "f"; echo "flock: ", $r10, "\n"; } catch (Throwable $e) { echo "flock: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r11 = fprintf($h, "x"); echo "fprintf: ", $r11, "\n"; } catch (Throwable $e) { echo "fprintf: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r12 = stream_copy_to_stream($h, $m2); echo "copy-from: ", $r12, "\n"; } catch (Throwable $e) { echo "copy-from: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r13 = stream_copy_to_stream($m2, $h); echo "copy-to: ", $r13, "\n"; } catch (Throwable $e) { echo "copy-to: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r14 = stream_set_chunk_size($h, 10); echo "chunk: ", $r14, "\n"; } catch (Throwable $e) { echo "chunk: ", get_class($e), ": ", $e->getMessage(), "\n"; }
$m = fopen("php://memory", "w+"); fwrite($m, "ab,cd"); rewind($m);
try { $v0 = fread($m, 0); echo "fread0: ", $v0, "\n"; } catch (Throwable $e) { echo "fread0: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $v1 = fread($m, -1); echo "fread-1: ", $v1, "\n"; } catch (Throwable $e) { echo "fread-1: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $v2 = stream_get_line($m, -5, ","); echo "sgl-5: ", $v2, "\n"; } catch (Throwable $e) { echo "sgl-5: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $v3 = stream_get_contents($m, -2); echo "sgc-2: ", $v3, "\n"; } catch (Throwable $e) { echo "sgc-2: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $v4 = stream_get_line($m, 4294967297, ","); echo "sgl-big: ", $v4, "\n"; } catch (Throwable $e) { echo "sgl-big: ", get_class($e), ": ", $e->getMessage(), "\n"; }
rewind($m);
echo "window: ", stream_get_line($m, 3, ",,"), "|", ftell($m), "\n";
file_put_contents("k4t.txt", "ab##rest");
$f = fopen("k4t.txt", "r");
echo "window-fd: ", stream_get_line($f, 3, "##"), "|", ftell($f), "\n";
fclose($f);
$f2 = fopen("k4t.txt", "r");
echo "big-fd: ", stream_get_line($f2, 4294967297, "#"), "\n";
$z = fopen("k4t.txt", "r"); fclose($z);
try { $q1 = fread($z, 5); echo "fread-fd: ", $q1, "\n"; } catch (Throwable $e) { echo "fread-fd: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { $q2 = feof($z); echo "feof-fd: ", $q2, "\n"; } catch (Throwable $e) { echo "feof-fd: ", get_class($e), ": ", $e->getMessage(), "\n"; }
unlink("k4t.txt");
$d = opendir("."); readdir($d); closedir($d);
$o = fopen("k4t-out.txt", "w");
try { closedir($d); echo "closedir2 ok\n"; } catch (Throwable $e) { echo "closedir2: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { readdir($d); echo "readdir ok\n"; } catch (Throwable $e) { echo "readdir: ", get_class($e), ": ", $e->getMessage(), "\n"; }
try { rewinddir($d); echo "rewinddir ok\n"; } catch (Throwable $e) { echo "rewinddir: ", get_class($e), ": ", $e->getMessage(), "\n"; }
echo fwrite($o, "hi"), "\n";
fclose($o);
echo file_get_contents("k4t-out.txt"), "\n";
unlink("k4t-out.txt");
"###,
    );
    assert_eq!(code, Some(0), "stderr: {stderr}");
    assert_eq!(
        stdout,
        "fread: TypeError: fread(): Argument #1 ($stream) must be an open stream resource\nfwrite: TypeError: fwrite(): Argument #1 ($stream) must be an open stream resource\nfgetc: TypeError: fgetc(): Argument #1 ($stream) must be an open stream resource\nfeof: TypeError: feof(): Argument #1 ($stream) must be an open stream resource\nftell: TypeError: ftell(): Argument #1 ($stream) must be an open stream resource\nrewind: TypeError: rewind(): Argument #1 ($stream) must be an open stream resource\nfseek: TypeError: fseek(): Argument #1 ($stream) must be an open stream resource\nsgc: TypeError: stream_get_contents(): Argument #1 ($stream) must be an open stream resource\nmeta: TypeError: stream_get_meta_data(): Argument #1 ($stream) must be an open stream resource\nsgl: TypeError: stream_get_line(): Argument #1 ($stream) must be an open stream resource\nflock: TypeError: flock(): Argument #1 ($stream) must be an open stream resource\nfprintf: TypeError: fprintf(): Argument #1 ($stream) must be an open stream resource\ncopy-from: TypeError: stream_copy_to_stream(): Argument #1 ($from) must be an open stream resource\ncopy-to: TypeError: stream_copy_to_stream(): Argument #2 ($to) must be an open stream resource\nchunk: TypeError: stream_set_chunk_size(): Argument #1 ($stream) must be an open stream resource\nfread0: ValueError: fread(): Argument #2 ($length) must be greater than 0\nfread-1: ValueError: fread(): Argument #2 ($length) must be greater than 0\nsgl-5: ValueError: stream_get_line(): Argument #2 ($length) must be greater than or equal to 0\nsgc-2: ValueError: stream_get_contents(): Argument #2 ($length) must be greater than or equal to -1\nsgl-big: ab\nwindow: ab,|3\nwindow-fd: ab#|3\nbig-fd: ab\nfread-fd: TypeError: fread(): Argument #1 ($stream) must be an open stream resource\nfeof-fd: TypeError: feof(): Argument #1 ($stream) must be an open stream resource\nclosedir2: TypeError: closedir(): Argument #1 ($dir_handle) must be an open stream resource\nreaddir: TypeError: readdir(): Argument #1 ($dir_handle) must be an open stream resource\nrewinddir: TypeError: rewinddir(): Argument #1 ($dir_handle) must be an open stream resource\n2\nhi\n"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// Without a `catch`, a closed-handle `TypeError` ends the program the way php's uncaught error
/// does: the fatal line on stderr and exit status 255.
#[test]
fn test_cli_wasm_uncaught_closed_handle_is_a_fatal() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_stream_guard_fatal");
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "main.php",
        r#"<?php
$h = fopen("php://memory", "w+");
fclose($h);
echo "before\n";
echo fread($h, 5);
echo "after\n";
"#,
    );
    assert_eq!(stdout, "before\n");
    assert!(
        stderr.contains("Uncaught TypeError: fread(): Argument #1 ($stream) must be an open stream resource"),
        "stderr: {stderr}"
    );
    assert_eq!(code, Some(255));
    let _ = fs::remove_dir_all(&dir);
}

/// `fgetc` boxes the one-byte string `fread` answered and used to leave the original block
/// behind, on the end-of-file arm too: a balanced loop kept growing memory. Twenty thousand and
/// eighty thousand calls must end at the same page count.
#[test]
fn test_cli_wasm_fgetc_does_not_leak() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_fgetc_leak");
    let source = |n: u32| {
        format!(
            r#"<?php
$h = fopen("php://memory", "w+");
fwrite($h, "ab");
$bytes = 0;
for ($i = 0; $i < {n}; $i++) {{
    rewind($h);
    $a = fgetc($h);
    $b = fgetc($h);
    $c = fgetc($h);
    $bytes += strlen($a) + strlen($b) + ($c === false ? 0 : 1);
}}
echo $bytes, "\n";
"#
        )
    };
    let (small_out, small_grew) = wasm_audit_run(&dir, "leak_small.php", &source(20_000));
    let (large_out, large_grew) = wasm_audit_run(&dir, "leak_large.php", &source(80_000));
    assert_eq!(small_out, "40000\n");
    assert_eq!(large_out, "160000\n");
    assert!(small_grew <= 2, "20000 fgetc rounds grew {small_grew} pages");
    assert!(large_grew <= small_grew + 1, "growth is not flat: {small_grew} then {large_grew} pages");
    let _ = fs::remove_dir_all(&dir);
}

/// `is_resource()` and `gettype()` of a CLOSED stream: php answers `false` and
/// `"resource (closed)"`, through a raw handle, a boxed array element, and every stream kind
/// (`php://output`, a memory stream, a real file, a directory handle, and `STDERR`).
///
/// The cell tag alone said resource forever, so a closed handle read as open.
#[test]
fn test_cli_wasm_is_resource_and_gettype_see_closed_streams() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_is_resource_closed");
    let source = r#"<?php
function show($label, $v) { echo $label, ":", is_resource($v) ? "open" : "closed", ":", gettype($v), "\n"; }
$h = fopen('php://memory','w+');
echo is_resource($h) ? "open":"closed", gettype($h), "\n";
fclose($h);
echo is_resource($h) ? "open":"closed", gettype($h), "\n";
$a = ['h' => fopen('php://output','w'), 'm' => fopen('php://memory','w+'), 'f' => fopen('r_file.txt','w'), 'd' => opendir('.')];
show('o0', $a['h']); show('m0', $a['m']); show('f0', $a['f']); show('d0', $a['d']);
fclose($a['h']); fclose($a['m']); fclose($a['f']); closedir($a['d']);
show('o1', $a['h']); show('m1', $a['m']); show('f1', $a['f']); show('d1', $a['d']);
echo is_resource(STDERR) ? "open":"closed", gettype(STDERR), "\n";
fclose(STDERR);
echo is_resource(STDERR) ? "open":"closed", gettype(STDERR), "\n";
echo is_resource(5) ? "open":"closed", is_resource(false) ? "open":"closed", "\n";
unlink('r_file.txt');
"#;
    let (stdout, _) = wasm_audit_run_with_preopen(&dir, "main.php", source, true);
    let expected = concat!(
        "openresource\nclosedresource (closed)\n",
        "o0:open:resource\nm0:open:resource\nf0:open:resource\nd0:open:resource\n",
        "o1:closed:resource (closed)\nm1:closed:resource (closed)\n",
        "f1:closed:resource (closed)\nd1:closed:resource (closed)\n",
        "openresource\nclosedresource (closed)\nclosedclosed\n",
    );
    assert_eq!(stdout, expected);
    if let Some(php) = wasm_optional_php_stdout(&dir, "main.php", source) {
        assert_eq!(php, expected);
    }
    let _ = fs::remove_dir_all(&dir);
}

/// `--target wasm32-wasi` never writes an `app.o`, so an unrelated directory of that name must
/// not refuse the build, and a tagged-PHP source named `app.o` (compiled directly or required by
/// the main file) must not be treated as an output it would overwrite. A native build still
/// plans the object, which the artifact_io unit tests cover.
#[test]
fn test_cli_wasm_does_not_plan_an_object_file() {
    let dir = make_cli_test_dir("elephc_cli_wasm_no_object_plan");
    fs::create_dir(dir.join("app.o")).unwrap();
    fs::write(dir.join("app.php"), "<?php echo 1;\n").unwrap();
    let built = elephc_cli_command(&dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(dir.join("app.php"))
        .output()
        .expect("failed to invoke elephc");
    assert!(
        built.status.success(),
        "a directory named app.o refused a WASM build: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    assert!(dir.join("app.wasm").is_file());
    fs::remove_dir(dir.join("app.o")).unwrap();

    let lib = "<?php\nfunction lib() { return 2; }\n";
    fs::write(dir.join("app.o"), lib).unwrap();
    fs::write(dir.join("main.php"), "<?php\nrequire 'app.o';\necho lib();\n").unwrap();
    let built = elephc_cli_command(&dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(dir.join("main.php"))
        .output()
        .expect("failed to invoke elephc");
    assert!(
        built.status.success(),
        "an included file named app.o refused a WASM build: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    assert_eq!(fs::read_to_string(dir.join("app.o")).unwrap(), lib);
    let direct = elephc_cli_command(&dir)
        .arg("--target")
        .arg("wasm32-wasi")
        .arg(dir.join("app.o"))
        .output()
        .expect("failed to invoke elephc");
    assert!(
        direct.status.success(),
        "a source named app.o refused a WASM build: {}",
        String::from_utf8_lossy(&direct.stderr)
    );
    assert_eq!(fs::read_to_string(dir.join("app.o")).unwrap(), lib);
    let _ = fs::remove_dir_all(&dir);
}

/// Pins the measured cost of the closed-stream tombstone: every `fopen("php://temp")`/`fclose`
/// pair keeps one 64-byte descriptor (80 bytes with the allocator header) behind, so the growth
/// is linear and small — 20000 pairs end at 23 pages and 80000 at 97 — rather than flat.
///
/// The tombstone is the price of answering "closed" through EVERY copy of a handle (a box, an
/// array element, a raw resource operand) without a refcount shared by those holders: freeing the
/// descriptor at `fclose` made any other copy read whatever reused its block. A shared refcount
/// would have to be threaded through every resource copy and release in the generic Mixed runtime,
/// which is disproportionate to 80 bytes per stream; this test fails if the cost ever grows.
#[test]
fn test_cli_wasm_memory_stream_tombstone_cost_is_bounded() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_memstream_churn");
    let source = |n: u32| {
        format!(
            "<?php\nfor ($i = 0; $i < {n}; $i++) {{ $h = fopen(\"php://temp\", \"w+\"); fclose($h); }}\necho \"done\\n\";\n"
        )
    };
    let (_, large) = wasm_audit_run(&dir, "churn_large.php", &source(80_000));
    let bytes_per_stream = large * 65_536 / 80_000;
    assert!(
        bytes_per_stream <= 96,
        "a closed memory stream now leaves {bytes_per_stream} bytes behind (measured 80)"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// Pins the cost of the per-open stream record: every `fopen("php://output")`/`fclose` pair keeps
/// one 8-byte record (24 with the allocator header) behind as the closed tombstone every copy of
/// the handle reads. Measured 40 bytes per pair, not 24, because the first-fit allocator hands the
/// record a freed 24-byte box block whole and the next box then grows the heap; the pre-record
/// baseline was 0. The runtime's own internal opens (`file_put_contents`,
/// `file_get_contents`) free theirs, so a loop of them stays flat.
#[test]
fn test_cli_wasm_stream_record_cost_is_bounded_and_internal_opens_are_flat() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_stream_record_cost");
    let (_, churn) = wasm_audit_run(
        &dir,
        "records.php",
        "<?php\nfor ($i = 0; $i < 80000; $i++) { $h = fopen('php://output', 'w'); fclose($h); }\necho \"done\\n\";\n",
    );
    let per_stream = churn * 65_536 / 80_000;
    assert!(
        per_stream <= 48,
        "a closed stream record now leaves {per_stream} bytes behind (measured 40)"
    );
    let (out, flat) = wasm_audit_run_with_preopen(
        &dir,
        "internal.php",
        "<?php\nfor ($i = 0; $i < 3000; $i++) { file_put_contents('f.txt', 'x'); $s = file_get_contents('f.txt'); }\necho $s, \"\\n\";\n",
        true,
    );
    assert_eq!(out, "x\n");
    assert!(flat <= 2, "internal opens leaked their stream records: {flat} pages");
    let _ = fs::remove_dir_all(&dir);
}

/// Closing one `php://output` stream must not close another, independently opened one: they used
/// to share the single pseudo-fd, so a stale copy of the closed stream kept writing and, worse,
/// the box `fclose` was given was the only thing marked.
///
/// Expected output is php 8.5's own.
#[test]
fn test_cli_wasm_php_output_streams_are_closed_independently() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_php_output_identity");
    let source = r#"<?php
$a = ['h' => fopen('php://output', 'w')];
$b = fopen('php://output', 'w');
fclose($a['h']);
try { fwrite($a['h'], 'x'); echo "|wrote"; } catch (TypeError $e) { echo "TypeError\n"; }
fwrite($b, "b-still-open\n");
$c = fopen('php://output', 'w');
$d = fopen('php://output', 'w');
fclose($d);
fwrite($c, "c-still-open\n");
try { fclose($d); echo "|closed-again"; } catch (TypeError $e) { echo "TypeError2\n"; }
try { fprintf($d, "%s", "y"); echo "|printed"; } catch (TypeError $e) { echo "TypeError3\n"; }
echo get_resource_type($d), " ", get_resource_type($c), "\n";
var_dump(fclose($c));
var_dump(fclose($b));
"#;
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(&dir, "main.php", source);
    assert_eq!(code, Some(0), "{stderr}");
    let expected = "TypeError\nb-still-open\nc-still-open\nTypeError2\nTypeError3\nUnknown stream\nbool(true)\nbool(true)\n";
    assert_eq!(stdout, expected);
    if let Some(php) = wasm_optional_php_stdout(&dir, "main.php", source) {
        assert_eq!(php, expected);
    }
    let _ = fs::remove_dir_all(&dir);
}

/// A stale copy of a closed real-file handle must stay closed after the host hands its fd number
/// to a new stream: it used to come back to life, so a write through it landed in the NEW file and
/// an `fclose` through it closed the new stream.
///
/// Expected output is php 8.5's own; the new stream's file is checked on disk.
#[test]
fn test_cli_wasm_stale_file_handle_stays_closed_after_fd_reuse() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_stale_file_handle");
    let source = r#"<?php
$a = fopen('a.txt', 'w');
$keep = ['h' => $a];
$alias = $keep['h'];
fclose($a);
$b = fopen('b.txt', 'w');
try { fwrite($keep['h'], "stale"); echo "wrote-stale\n"; } catch (TypeError $e) { echo "write TypeError\n"; }
try { fwrite($alias, "stale"); echo "wrote-alias\n"; } catch (TypeError $e) { echo "alias TypeError\n"; }
try { fclose($keep['h']); echo "closed-stale\n"; } catch (TypeError $e) { echo "close TypeError\n"; }
echo get_resource_type($keep['h']), " ", get_resource_type($b), "\n";
fwrite($b, "B-content");
var_dump(fclose($b));
echo file_get_contents('b.txt'), "|", file_get_contents('a.txt'), "|\n";
"#;
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(&dir, "main.php", source);
    assert_eq!(code, Some(0), "{stderr}");
    let expected = "write TypeError\nalias TypeError\nclose TypeError\nUnknown stream\nbool(true)\nB-content||\n";
    assert_eq!(stdout, expected);
    assert_eq!(fs::read_to_string(dir.join("b.txt")).unwrap(), "B-content");
    assert_eq!(fs::read_to_string(dir.join("a.txt")).unwrap(), "");
    if let Some(php) = wasm_optional_php_stdout(&dir, "main.php", source) {
        assert_eq!(php, expected);
    }
    let _ = fs::remove_dir_all(&dir);
}

/// The same identity rule across kinds: a closed directory handle must not come back when `fopen`
/// reuses its fd, and a closed file handle must not when `opendir` does.
#[test]
fn test_cli_wasm_stale_directory_handle_stays_closed_after_fd_reuse() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_stale_dir_handle");
    let source = r#"<?php
$d = opendir('.');
$keep = ['d' => $d];
closedir($d);
$f = fopen('x.txt', 'w');
try { readdir($keep['d']); echo "read\n"; } catch (TypeError $x) { echo "readdir TypeError\n"; }
try { closedir($keep['d']); echo "closed\n"; } catch (TypeError $x) { echo "closedir TypeError\n"; }
fwrite($f, "still-open");
var_dump(fclose($f));
echo file_get_contents('x.txt'), "\n";
$g = fopen('x.txt', 'r');
$gk = ['g' => $g];
fclose($g);
$e2 = opendir('.');
try { fread($gk['g'], 1); echo "fread\n"; } catch (TypeError $x) { echo "fread TypeError\n"; }
try { fclose($gk['g']); echo "fclosed\n"; } catch (TypeError $x) { echo "fclose TypeError\n"; }
echo is_string(readdir($e2)) ? "dir-still-open\n" : "dir-broken\n";
var_dump(closedir($e2));
"#;
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(&dir, "main.php", source);
    assert_eq!(code, Some(0), "{stderr}");
    let expected = "readdir TypeError\nclosedir TypeError\nbool(true)\nstill-open\nfread TypeError\nfclose TypeError\ndir-still-open\nNULL\n";
    assert_eq!(stdout, expected);
    let _ = fs::remove_dir_all(&dir);
}

/// `php://stdout|stderr|stdin` opens are streams of their own: closing one leaves the process fd
/// (and the `STDOUT` constant) working, and a copy of the closed handle reads as closed. Closing
/// the `STDERR` constant makes every copy of it read as closed too, as in php; the host fd stays
/// open (a deliberate divergence, so `echo` and the uncaught-error path keep working).
///
/// Expected output is php 8.5's own.
#[test]
fn test_cli_wasm_standard_stream_opens_and_constants_close_like_php() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_std_stream_identity");
    let source = r#"<?php
$o = fopen('php://stdout', 'w');
$c = [$o];
var_dump(fclose($o));
try { fwrite($c[0], "x"); echo "wrote\n"; } catch (TypeError $e) { echo "TE1\n"; }
$o2 = fopen('php://stdout', 'w');
fwrite($o2, "second-open-works\n");
fwrite(STDOUT, "constant-works\n");
$a = fopen('php://stdin', 'r');
fclose($a);
try { fread($a, 1); } catch (TypeError $e) { echo "TE2\n"; }
$err = STDERR;
echo get_resource_type($err), "\n";
fclose(STDERR);
echo "ok\n";
try { fwrite($err, "z"); echo "w\n"; } catch (TypeError $x) { echo "TE-err\n"; }
echo get_resource_type($err), "\n";
try { fclose($err); echo "again\n"; } catch (TypeError $x) { echo "TE-again\n"; }
"#;
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(&dir, "main.php", source);
    assert_eq!(code, Some(0), "{stderr}");
    let expected = "bool(true)\nTE1\nsecond-open-works\nconstant-works\nTE2\nstream\nok\nTE-err\nUnknown\nTE-again\n";
    assert_eq!(stdout, expected);
    if let Some(php) = wasm_optional_php_stdout(&dir, "main.php", source) {
        assert_eq!(php, expected);
    }
    let _ = fs::remove_dir_all(&dir);
}

/// `php://output` is the output buffer, not stdout: writes through it are captured by `ob_start`
/// (and by nested buffers and handlers), while `php://stdout` bypasses the buffers. It used to
/// share fd 1 with `php://stdout`, so `ob_get_clean()` returned an empty string.
///
/// The handle also answers php's own `fclose`/`feof`/`ftell` and reports `PHP`/`Output`/`wb`.
#[test]
fn test_cli_wasm_php_output_goes_through_output_buffering() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_php_output_ob");
    let source = r#"<?php
$h = fopen('php://output', 'w');
echo "plain:";
var_dump(fwrite($h, "ab\n"));
var_dump(feof($h));
var_dump(ftell($h));
$m = stream_get_meta_data($h);
echo $m['wrapper_type'], " ", $m['stream_type'], " ", $m['mode'], " ", $m['uri'], " ", $m['seekable'] ? 'seekable' : 'unseekable', "\n";
var_dump(fprintf($h, "%d|%s\n", 5, "p"));
$s = fopen('php://memory', 'w+');
fwrite($s, "copy\n");
rewind($s);
var_dump(stream_copy_to_stream($s, $h));
ob_start();
fwrite($h, "in");
fprintf($h, "%s", "-fmt");
$x = ob_get_clean();
echo "[", $x, "]\n";
ob_start();
ob_start(fn($b) => strtoupper($b));
fwrite($h, "nest");
ob_end_flush();
$y = ob_get_clean();
echo "[", $y, "]\n";
ob_start();
$o = fopen('php://stdout', 'w');
fwrite($o, "direct\n");
$z = ob_get_clean();
echo "[", $z, "]\n";
var_dump(fclose($h));
echo "after\n";
"#;
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(&dir, "main.php", source);
    assert_eq!(code, Some(0), "stderr: {stderr}");
    let expected = "plain:ab\nint(3)\nbool(false)\nint(3)\nPHP Output wb php://output unseekable\n5|p\nint(4)\ncopy\nint(5)\n[in-fmt]\n[NEST]\ndirect\n[]\nbool(true)\nafter\n";
    assert_eq!(stdout, expected);
    if let Some(php) = wasm_optional_php_stdout(&dir, "oracle.php", source) {
        assert_eq!(php, expected, "the pinned text drifted from php");
    }
    let _ = fs::remove_dir_all(&dir);
}

/// A compilation input inside the npm package directory is refused, not overwritten.
///
/// Publication replaces every generated file in `app-npm/` (`README.md` included), but only
/// `module.wasm` used to be protected, so `require "app-npm/README.md"` read a file the same
/// build then replaced. The refusal names the package and leaves the input unchanged.
#[test]
fn test_cli_wasm_npm_refuses_an_input_inside_the_package_directory() {
    let dir = make_cli_test_dir("elephc_cli_wasm_npm_input");
    let app = dir.join("app.php");
    fs::write(&app, "<?php\necho \"first\\n\";\n").unwrap();
    let first = elephc_cli_command(&dir)
        .args(["--target", "wasm32-wasi", "--emit", "npm"])
        .arg(&app)
        .output()
        .expect("failed to invoke elephc");
    assert!(first.status.success(), "{}", String::from_utf8_lossy(&first.stderr));
    let readme = dir.join("app-npm").join("README.md");
    let tagged = "<?php\nfunction lib() { return \"lib\"; }\n";
    fs::write(&readme, tagged).unwrap();
    fs::write(&app, "<?php\nrequire \"app-npm/README.md\";\necho lib(), \"\\n\";\n").unwrap();
    let second = elephc_cli_command(&dir)
        .args(["--target", "wasm32-wasi", "--emit", "npm"])
        .arg(&app)
        .output()
        .expect("failed to invoke elephc");
    let stderr = String::from_utf8_lossy(&second.stderr);
    assert!(!second.status.success(), "the build must be refused");
    assert!(
        stderr.contains("refusing to write the npm package") && stderr.contains("README.md"),
        "stderr: {stderr}"
    );
    assert_eq!(fs::read_to_string(&readme).unwrap(), tagged, "the input was overwritten");
    let _ = fs::remove_dir_all(&dir);
}

/// `tmpfile()` claims its name with an exclusive create, so a name another module takes between
/// the choice and the open is skipped and its file is left alone.
///
/// An existence probe followed by a truncating `w+` open had exactly that window. The runner
/// below plays the OTHER module: the first time the program touches `.elephc_tmp000` (the probe
/// of the old code, the open of the new one) it creates that file with its own content, once.
/// The old open then truncated it; the exclusive open fails and moves on to `.elephc_tmp001`.
/// Pre-existing `.elephc_tmp001` and `.elephc_tmp002` files must come through untouched too.
#[test]
fn test_cli_wasm_tmpfile_claims_its_name_exclusively() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_tmpfile_excl");
    fs::write(dir.join(".elephc_tmp001"), "keep one").unwrap();
    fs::write(dir.join(".elephc_tmp002"), "keep two").unwrap();
    let runner = dir.join("run_race.mjs");
    fs::write(
        &runner,
        r#"import { readFileSync, existsSync, writeFileSync } from "node:fs";
import { WASI } from "node:wasi";
const wasi = new WASI({ version: "preview1", args: ["m"], env: {}, returnOnExit: true, preopens: { ".": "." } });
const imports = wasi.getImportObject();
const wasip1 = imports.wasi_snapshot_preview1;
let memory = null;
let raced = false;
const nameAt = (ptr, len) => Buffer.from(memory.buffer, ptr, len).toString();
const rival = () => {
  if (!raced && !existsSync(".elephc_tmp000")) {
    writeFileSync(".elephc_tmp000", "other module");
    raced = true;
  }
};
const probe = wasip1.path_filestat_get;
wasip1.path_filestat_get = (fd, flags, ptr, len, buf) => {
  const named = nameAt(ptr, len) === ".elephc_tmp000";
  const result = probe(fd, flags, ptr, len, buf);
  if (named) rival();
  return result;
};
const open = wasip1.path_open;
wasip1.path_open = (fd, dirflags, ptr, len, ...rest) => {
  if (nameAt(ptr, len) === ".elephc_tmp000") rival();
  return open(fd, dirflags, ptr, len, ...rest);
};
const instance = await WebAssembly.instantiate(
  await WebAssembly.compile(readFileSync(process.argv[2])),
  imports,
);
memory = instance.exports.memory;
process.exitCode = wasi.start(instance);
"#,
    )
    .unwrap();
    let path = dir.join("main.php");
    fs::write(
        &path,
        r#"<?php
$t = tmpfile();
fwrite($t, "payload");
rewind($t);
echo fread($t, 100), "\n";
fclose($t);
"#,
    )
    .unwrap();
    let built = elephc_cli_command(&dir)
        .args(["--target", "wasm32-wasi"])
        .arg(&path)
        .output()
        .expect("failed to invoke elephc");
    assert!(built.status.success(), "{}", String::from_utf8_lossy(&built.stderr));
    let run = node_command()
        .arg("--no-warnings")
        .arg(&runner)
        .arg(dir.join("main.wasm"))
        .current_dir(&dir)
        .output()
        .expect("failed to run under Node");
    let stderr = String::from_utf8_lossy(&run.stderr);
    assert_eq!(run.status.code(), Some(0), "{stderr}");
    assert_eq!(String::from_utf8_lossy(&run.stdout), "payload\n");
    assert_eq!(
        fs::read_to_string(dir.join(".elephc_tmp000")).unwrap_or_else(|e| format!("<{e}>")),
        "other module",
        "tmpfile() truncated a file another module created"
    );
    assert_eq!(fs::read_to_string(dir.join(".elephc_tmp001")).unwrap(), "keep one");
    assert_eq!(fs::read_to_string(dir.join(".elephc_tmp002")).unwrap(), "keep two");
    assert!(!dir.join(".elephc_tmp003").exists(), "the temp file survived fclose");
    let _ = fs::remove_dir_all(&dir);
}

/// Verifies every `tmpfile()` the program closes is deleted, up to the last name available.
///
/// The fd's table byte stores the temp index + 1 so that 0 can mean "not a temp file"; index 255
/// wrapped to 0, so the 256th temporary file survived its `fclose`. Names now stop at 255.
#[test]
fn test_cli_wasm_every_closed_tmpfile_is_deleted() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_tmpfile_wrap");
    let source = r#"<?php
$hs = [];
for ($i = 0; $i < 256; $i++) {
    $t = tmpfile();
    if ($t !== false) { $hs[] = $t; }
}
echo count($hs), "\n";
foreach ($hs as $h) { fclose($h); }
echo "closed\n";
"#;
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(&dir, "main.php", source);
    assert_eq!(code, Some(0), "{stderr}");
    assert_eq!(stdout, "255\nclosed\n");
    let leftovers: Vec<String> = fs::read_dir(&dir)
        .expect("test dir")
        .filter_map(|entry| entry.ok())
        .map(|entry| entry.file_name().to_string_lossy().into_owned())
        .filter(|name| name.contains("elephc_tmp"))
        .collect();
    assert!(leftovers.is_empty(), "temporary files survived fclose: {leftovers:?}");
    let _ = fs::remove_dir_all(&dir);
}
/// Runs `source` under a live `php -n` when one is installed and answers its stdout, or `None`
/// where there is no php (CI containers have none). The pinned expected text is the assertion;
/// this only cross-checks it when it can.
fn wasm_optional_php_stdout(dir: &std::path::Path, name: &str, source: &str) -> Option<String> {
    let path = dir.join(name);
    fs::write(&path, source).ok()?;
    let out = Command::new("php").arg("-n").arg(&path).current_dir(dir).output().ok()?;
    Some(String::from_utf8_lossy(&out.stdout).to_string())
}

/// PHP method names are case-insensitive. The lowering formed the callee symbol and looked the
/// body's parameters up with the CALL-SITE spelling, so `A::F(5)` against a method declared `f`
/// produced a module that failed validation with "unknown func". A class `Ab` must also not
/// change how a call on `A` treats a `void` body.
#[test]
fn test_cli_wasm_method_calls_are_case_insensitive() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_method_case");
    let source = r#"<?php
class A {
    public static function f(mixed $x): int { return 1; }
    public function inst(mixed $x): int { return 2; }
    public static function nothing(): void {}
    public static function val(): int { return 11; }
}
class Ab {
    public static function nothing(): int { return 7; }
    public static function val(): void {}
}
class B extends A {
    public function viaParent(): int { return parent::F(5) + parent::INST(6); }
}
echo A::F(5), "\n";
echo A::f(5), "\n";
$a = new A();
echo $a->INST(5), "\n";
echo $a?->Inst(5), "\n";
$b = new B();
echo $b->viaParent(), "\n";
var_dump(A::NOTHING());
echo Ab::Nothing(), "\n";
echo A::val(), "\n";
var_dump(Ab::val());
"#;
    let (stdout, _) = wasm_audit_run(&dir, "case.php", source);
    assert_eq!(stdout, "1\n1\n2\n2\n3\nNULL\n7\n11\nNULL\n");
    if let Some(php) = wasm_optional_php_stdout(&dir, "case_php.php", source) {
        assert_eq!(stdout, php);
    }
    let _ = fs::remove_dir_all(&dir);
}

/// A generator's frame holds values, not a borrowed reference cell, so a by-reference parameter
/// on a generator function used to panic the compiler (`index out of bounds` in the prologue).
/// It is refused by name in the capability audit instead.
#[test]
fn test_cli_wasm_generator_by_reference_parameter_is_refused_by_name() {
    let dir = make_cli_test_dir("elephc_cli_wasm_generator_byref");
    let stderr = wasm_audit_refusal(
        &dir,
        "genref.php",
        "<?php\nfunction g(&$x) { $y = $x; yield $y; }\n$v0 = 5;\nforeach (g($v0) as $v) { echo $v; }\n",
    );
    assert!(
        stderr.contains("generator with by-reference parameter $x"),
        "the refusal must name the shape: {stderr}"
    );
    assert!(!stderr.contains("panicked"), "the compiler must not panic: {stderr}");
    let _ = fs::remove_dir_all(&dir);
}

/// The `@` operator silences every PHP-level diagnostic, deprecations included. `$s[10]`'s
/// "Uninitialized string offset", the `chr()`/`ord()` range deprecations, the NaN coercion
/// diagnostics and the null-argument deprecation were written without the `$__diag_suppress`
/// gate the other warnings use, so `@$s[10]` still printed.
#[test]
fn test_cli_wasm_error_suppression_silences_every_diagnostic() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_diag_suppress");
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "suppress.php",
        r#"<?php
$s = "";
$c = @$s[10];
echo @chr(300) === chr(44) ? "c" : "x";
echo @ord("ab");
$n = $argc > 5 ? 1.0 : NAN;
$b = @(bool)$n;
echo @strlen($argc > 5 ? "a" : null);
echo "ok\n";
$t = $s[10];
"#,
    );
    assert_eq!(code, Some(0));
    assert_eq!(stdout, "c970ok\n");
    // The unsuppressed read at the end is the control: only it may print.
    assert_eq!(stderr, "Warning: Uninitialized string offset 10\n");
    let _ = fs::remove_dir_all(&dir);
}

/// A boxed value feeding `%`, `<<`, `>>`, `&`, `|` or `^` is coerced under php's own contract:
/// a leading-numeric string ("5 apples") answers its prefix after `Warning: A non-numeric value
/// encountered`, and a float-string saturates (it never traps on an out-of-range value).
/// `__rt_mixed_arith_int` only knew the wholly numeric classes, so `"5 apples" % 3` was a fatal
/// TypeError and `"1e30" | 1` executed an unchecked `i64.trunc_f64_s`.
///
/// Expected output and diagnostics were measured against php 8.5 (`display_errors=stderr`).
#[test]
fn test_cli_wasm_integer_operators_coerce_leading_numeric_strings() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_arith_int_coerce");
    let source = r#"<?php
function t(mixed $m): void {
  echo "[", $m % 4, ",", $m << 1, ",", $m >> 1, ",", $m & 6, ",", $m | 8, ",", $m ^ 5, "]\n";
}
foreach (["5 apples", " 7", "7 ", "1e3x", "0x1A", "9223372036854775808", "1.5", "1.5x", "-3 z", "1e30", "-1e30", "1e999", "9.3e18x", "-9223372036854775809"] as $v) {
  echo $v, " => ";
  t($v);
}
$m = $argc > 0 ? "5 apples" : 1;
echo $m % 3, "\n";
"#;
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(&dir, "arith_int.php", source);
    assert_eq!(code, Some(0), "stderr: {stderr}");
    assert_eq!(
        stdout,
        "5 apples => [1,10,2,4,13,0]\n 7 => [3,14,3,6,15,2]\n7  => [3,14,3,6,15,2]\n\
         1e3x => [0,2000,500,0,1000,1005]\n0x1A => [0,0,0,0,8,5]\n\
         9223372036854775808 => [3,-2,4611686018427387903,6,9223372036854775807,9223372036854775802]\n\
         1.5 => [1,2,0,0,9,4]\n1.5x => [1,2,0,0,9,4]\n-3 z => [-3,-6,-2,4,-3,-8]\n\
         1e30 => [3,-2,4611686018427387903,6,9223372036854775807,9223372036854775802]\n\
         -1e30 => [0,0,-4611686018427387904,0,-9223372036854775800,-9223372036854775803]\n\
         1e999 => [0,0,0,0,8,5]\n\
         9.3e18x => [3,-2,4611686018427387903,6,9223372036854775807,9223372036854775802]\n\
         -9223372036854775809 => [0,0,-4611686018427387904,0,-9223372036854775800,-9223372036854775803]\n2\n"
    );
    assert_eq!(stderr.matches("Warning: A non-numeric value encountered\n").count(), 37);
    for text in ["-1e30", "1.5", "1.5x", "1e30", "1e999", "9.3e18x"] {
        let line = format!(
            "Deprecated: Implicit conversion from float-string \"{text}\" to int loses precision\n"
        );
        assert_eq!(stderr.matches(&line).count(), 6, "{text}: {stderr}");
    }
    let _ = fs::remove_dir_all(&dir);
}

/// `(float)` of a subnormal decimal string used to answer 0 because the parser short-circuited
/// every magnitude under 1e-308. `(float)"5e-324"` is the smallest positive double.
///
/// Expected text is php 8.5's own (`php -n`).
#[test]
fn test_cli_wasm_subnormal_float_strings_parse_correctly() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_subnormal_strings");
    let source = r#"<?php
function same(string $s, float $lit): string { return (float)$s === $lit ? "eq" : "ne"; }
echo same("5e-324", 5e-324), same("4.9e-324", 4.9e-324), same("4.9e-324", 5e-324), "\n";
echo same("2.2250738585072009e-308", 2.2250738585072009e-308), same("2.2250738585072014e-308", 2.2250738585072014e-308), same("2.2250738585072009e-308", 2.2250738585072014e-308), "\n";
echo same("1e-310", 1e-310), same("1e-323", 1e-323), same("2.4703282292062327e-324", 0.0), same("2.4703282292062328e-324", 5e-324), "\n";
echo same("-5e-324", -5e-324), same("1e-325", 0.0), same("123456789e-330", 123456789e-330), same("9e-320", 9e-320), "\n";
$s = $argc > 5 ? "1" : "5e-324";
echo (float)$s > 0 ? "positive" : "zero", "\n";
echo (float)"1e-310" * 1e300 > 0 ? "positive" : "zero", "\n";
"#;
    let (stdout, _) = wasm_audit_run(&dir, "subnormal.php", source);
    assert_eq!(
        stdout,
        "eqeqeq\neqeqne\neqeqeqeq\neqeqeqeq\npositive\npositive\n"
    );
    if let Some(php) = wasm_optional_php_stdout(&dir, "subnormal_php.php", source) {
        assert_eq!(stdout, php);
    }
    let _ = fs::remove_dir_all(&dir);
}

/// `array_pad()` with a size past php's array limit (2^30 in magnitude, `PHP_INT_MIN` included
/// because its negation wraps) raises a catchable `ValueError` before allocating anything. The
/// WASM helper used to try the allocation and die with "Allowed memory size exhausted".
///
/// Expected text is php 8.5's own (`php -n`).
#[test]
fn test_cli_wasm_array_pad_oversized_length_is_a_catchable_value_error() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_array_pad_limit");
    let source = r#"<?php
foreach ([PHP_INT_MAX, PHP_INT_MIN, 4, -4, 1, 0, 1073741825, -1073741825, 2147483647, -2147483648] as $n) {
  try {
    $r = array_pad([1, 2], $n, 0);
    echo $n, " => ", implode(",", $r), "\n";
  } catch (Throwable $e) { echo $n, " => ", get_class($e), ": ", $e->getMessage(), "\n"; }
}
$r = array_pad([1], PHP_INT_MAX, 0);
echo "unreachable\n";
"#;
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(&dir, "pad_limit.php", source);
    let limit = "ValueError: array_pad(): Argument #2 ($length) must not exceed the maximum allowed array size";
    assert_eq!(
        stdout,
        format!(
            "9223372036854775807 => {limit}\n-9223372036854775808 => {limit}\n4 => 1,2,0,0\n\
             -4 => 0,0,1,2\n1 => 1,2\n0 => 1,2\n1073741825 => {limit}\n-1073741825 => {limit}\n\
             2147483647 => {limit}\n-2147483648 => {limit}\n"
        )
    );
    assert_eq!(code, Some(255));
    assert_eq!(stderr, format!("PHP Fatal error: Uncaught {limit}\n"));
    let _ = fs::remove_dir_all(&dir);
}

/// A statically array-typed operand can still be a null pointer at run time (a missed element
/// read of an `array<array<int>>`). php raises a catchable `TypeError` naming the operands; the
/// union and merge helpers used to dereference the null and TRAP with `memory access out of
/// bounds`. Two nulls are php's integer 0, which an array-typed result cannot hold, so that one
/// stops with a named fatal instead.
///
/// Expected text is php 8.5's own (`php -n`).
#[test]
fn test_cli_wasm_null_array_operands_raise_php_type_errors() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_null_array_operands");
    let source = r#"<?php
$g = [[1, 2]];
try { $r1 = $g[3] + [7]; echo "no throw\n"; } catch (Throwable $e) { echo get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r2 = [7] + $g[3]; echo "no throw\n"; } catch (Throwable $e) { echo get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r3 = array_merge($g[0], $g[3]); echo "no throw\n"; } catch (Throwable $e) { echo get_class($e), ": ", $e->getMessage(), "\n"; }
try { $r4 = array_merge($g[3], $g[0]); echo "no throw\n"; } catch (Throwable $e) { echo get_class($e), ": ", $e->getMessage(), "\n"; }
$z = $g[3] + [7];
echo "unreachable\n";
"#;
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(&dir, "null_operands.php", source);
    assert_eq!(
        stdout,
        "TypeError: Unsupported operand types: null + array\n\
         TypeError: Unsupported operand types: array + null\n\
         TypeError: array_merge(): Argument #2 must be of type array, null given\n\
         TypeError: array_merge(): Argument #1 must be of type array, null given\n"
    );
    assert_eq!(code, Some(255));
    assert!(
        stderr.ends_with("PHP Fatal error: Uncaught TypeError: Unsupported operand types: null + array\n"),
        "an uncaught null + array must report php's TypeError: {stderr}"
    );
    assert!(!stderr.contains("RuntimeError"), "the module must not trap: {stderr}");

    let (_, stderr, code) = wasm_audit_run_to_fatal(
        &dir,
        "null_both.php",
        "<?php\n$g = [[1, 2]];\n$z = $g[4] + $g[5];\necho \"unreachable\\n\";\n",
    );
    assert_eq!(code, Some(255));
    assert!(
        stderr.contains("`+` of two null operands evaluates to int 0 in php"),
        "null + null must stop by name: {stderr}"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// A closure stored in a heterogeneous array is a refcounted callable cell (value tag 10).
/// `__rt_hash_free_deep` released tags 4-7 but not 10, so every such array leaked its closure
/// when it died. The store itself also kept the fresh temporary's own reference, so an array, an
/// object or a closure written straight into a hash literal leaked one reference as well.
/// 20000 and 80000 iterations must end at the same page count for each shape.
#[test]
fn test_cli_wasm_hash_stores_release_container_values() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_hash_callable_leak");
    let source = |body: &str, n: u32| {
        format!("<?php\nclass Box {{ public int $v = 1; }}\nfor ($i = 0; $i < {n}; $i++) {{\n  {body}\n}}\necho \"done\\n\";\n")
    };
    for (index, body) in [
        "$h = ['k' => function() { return 1; }, 'n' => 1]; $h = [];",
        "$h = ['k' => [1, 2], 'n' => 1]; $h = [];",
        "$h = ['k' => new Box(), 'n' => 1]; $h = null;",
    ]
    .iter()
    .enumerate()
    {
        let (out, small) = wasm_audit_run(&dir, &format!("owned_small_{index}.php"), &source(body, 20_000));
        let (_, large) = wasm_audit_run(&dir, &format!("owned_large_{index}.php"), &source(body, 80_000));
        assert_eq!(out, "done\n");
        assert!(
            large - small <= 1,
            "`{body}` leaked: {small} pages at 20000 iterations, {large} at 80000"
        );
    }
    let _ = fs::remove_dir_all(&dir);
}

/// An output handler that throws re-raised its exception without releasing the `[$buffer,
/// $phase]` argument array it had built for the call, so every caught throw leaked that array and
/// its two cells. 20000 and 80000 caught throws must end at the same page count.
///
/// The handler takes no parameters so that only the handler's own arguments are measured: a
/// closure wrapper that is unwound by a throw also strands its private string-parameter copy,
/// which is a separate cost of throwing through ANY runtime-invoked callback.
#[test]
fn test_cli_wasm_throwing_output_handler_does_not_leak_its_arguments() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_ob_handler_throw_leak");
    let source = |n: u32| {
        format!(
            "<?php\nfor ($i = 0; $i < {n}; $i++) {{\n  try {{\n    ob_start(function () {{ throw new Exception(\"x\"); }});\n    ob_end_flush();\n  }} catch (Exception $e) {{\n  }}\n}}\necho \"done\\n\";\n"
        )
    };
    let (out, small) = wasm_audit_run(&dir, "ob_throw_small.php", &source(20_000));
    let (_, large) = wasm_audit_run(&dir, "ob_throw_large.php", &source(80_000));
    assert_eq!(out, "done\n");
    assert!(
        large - small <= 1,
        "a throwing output handler leaked its arguments: {small} pages at 20000 iterations, {large} at 80000"
    );
    let _ = fs::remove_dir_all(&dir);
}

/// php finishes off a buffer level whose handler throws: the handler is disabled, the buffer's
/// own bytes pass through (or are discarded for `ob_end_clean`/`ob_get_clean`), the level is
/// gone, and only then does the exception reach a `catch`. The exception used to leave the level
/// live, so the program's later output was captured by it and the exit-time flush ran the
/// throwing handler a second time into an uncatchable fatal.
///
/// Expected text is php 8.5's own (`php -n`).
#[test]
fn test_cli_wasm_throwing_output_handler_finishes_its_level_first() {
    if node_missing_skips_test() {
        return;
    }
    let dir = make_cli_test_dir("elephc_cli_wasm_ob_handler_throw_level");
    let source = r#"<?php
for ($i = 0; $i < 3; $i++) {
  try {
    ob_start(function ($b, $p) { throw new Exception("x"); });
    echo "hello";
    ob_end_flush();
  } catch (Exception $e) { echo "caught\n"; }
}
try {
  ob_start(function ($b, $p) { throw new Exception("y"); });
  echo "gone";
  ob_end_clean();
} catch (Exception $e) { echo "caught2\n"; }
try {
  ob_start(function ($b, $p) { throw new Exception("z"); });
  echo "gone";
  $s = ob_get_clean();
  echo "unreachable\n";
} catch (Exception $e) { echo "caught3\n"; }
echo count(ob_get_status()), "\n";
echo "done\n";
"#;
    let (stdout, stderr, code) = wasm_audit_run_to_fatal(&dir, "ob_throw_level.php", source);
    assert_eq!(code, Some(0), "stderr: {stderr}");
    assert_eq!(
        stdout,
        "hellocaught\nhellocaught\nhellocaught\ncaught2\ncaught3\n0\ndone\n"
    );
    if let Some(php) = wasm_optional_php_stdout(&dir, "ob_throw_level_php.php", source) {
        assert_eq!(stdout, php);
    }
    let _ = fs::remove_dir_all(&dir);
}
